// debug helper function to read back pixels of a single mip level and array layer of an image
void Image::readback_pixels(Semaphore* semaphore, uint32_t array_layer, uint32_t mip_level, uint32_t start_pixel, uint32_t pixel_count) {
	// 1) Create staging buffer large enough for image
	uint32_t pixel_bytes = get_format_bytes_per_pixel(this->format);
	VkDeviceSize image_size = this->extent.width * this->extent.height * pixel_bytes;

	auto& manager = VulkanManager::get_singleton();
	auto& task = manager.get_graphics_task();
	auto& cb = task.get_command_buffer();

	// Create host-visible buffer 'staging' with VK_BUFFER_USAGE_TRANSFER_DST_BIT and memory property HOST_VISIBLE|HOST_COHERENT
	auto& staging_buffer = task.make_buffer<char8_t>(image_size, BufferType::TRANSFER_BUFFER, VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT);

	// 2) Copy image subresource (mip, face) -> buffer
	cb.begin_recording();

	// Transition image subresource to TRANSFER_SRC_OPTIMAL (only the target layer/mip)
	VkImageSubresourceRange range{};
	range.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
	range.baseMipLevel = mip_level;
	range.levelCount = 1;
	range.baseArrayLayer = array_layer;
	range.layerCount = 1;
	cb.transition_image_layout(*this, VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL, range);

	VkBufferImageCopy region{};
	region.bufferOffset = 0;
	region.bufferRowLength = 0;
	region.bufferImageHeight = 0;
	region.imageSubresource.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
	region.imageSubresource.mipLevel = mip_level;
	region.imageSubresource.baseArrayLayer = array_layer;
	region.imageSubresource.layerCount = 1;
	region.imageOffset = { 0,0,0 };
	region.imageExtent = { this->extent.width, this->extent.height, 1 };

	vkCmdCopyImageToBuffer(cb.get(), this->image, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL, staging_buffer.get(), 1, &region);

	// Add Buffer Memory Barrier to synchronize GPU write -> CPU read
	cb.add_buffer_memory_barrier(
		staging_buffer,
		VK_ACCESS_TRANSFER_WRITE_BIT,       // srcAccessMask (GPU finished writing)
		VK_ACCESS_HOST_READ_BIT,            // dstAccessMask (CPU will read)
		VK_PIPELINE_STAGE_TRANSFER_BIT,     // srcStageMask
		VK_PIPELINE_STAGE_HOST_BIT          // dstStageMask
	);
	cb.record_barriers();

	// Transition back
	cb.transition_image_layout(*this, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL, VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL, range);
	cb.end_recording();
	task.timeline_sync(*semaphore);
	task.submit();
	task.get_fence().wait();

	// 3) Map staging buffer and inspect pixels
	void* data = staging_buffer.map(0, image_size);
	staging_buffer.invalidate(0, image_size);

	// Print pixel values
	uint32_t end_pixel = start_pixel + pixel_count;
	Log::force("\nPIXEL READBACK FROM IMAGE VkImage=", this->image, ", ARRAY LAYER ", array_layer, ", MIP_LEVEL ", mip_level, ", PIXELS ", start_pixel, "-", end_pixel);
	uint32_t channels = has_alpha(this->format) ? 4 : 3;
	uint32_t color_bytes = pixel_bytes / channels;
	if (color_bytes == 1) {
		uint8_t* p = reinterpret_cast<uint8_t*>(data);
		for (uint32_t pixel = start_pixel; pixel < end_pixel; pixel++) {
			Log::force("Pixel ", pixel, ": {",
				static_cast<uint32_t>(p[pixel * channels + 0]), ", ",	// R
				static_cast<uint32_t>(p[pixel * channels + 1]), ", ",	// G
				static_cast<uint32_t>(p[pixel * channels + 2]),			// B
				channels == 4 ? (", " + std::to_string(static_cast<uint32_t>(p[pixel * channels + 3]))) : "", // A
				"}"
			);
		}
	}
	else if (color_bytes == 2) {
		uint16_t* p = reinterpret_cast<uint16_t*>(data);
		for (uint32_t pixel = start_pixel; pixel < end_pixel; pixel++) {
			Log::force("Pixel ", pixel, ": {",
				static_cast<uint32_t>(p[pixel * channels + 0]), ", ",	// R
				static_cast<uint32_t>(p[pixel * channels + 1]), ", ",	// G
				static_cast<uint32_t>(p[pixel * channels + 2]),			// B
				channels == 4 ? (", " + std::to_string(static_cast<float_t>(p[pixel * channels + 3]))) : "", // A
				"}"
			);
		}
	}
	else if (color_bytes == 4) {
		float_t* p = reinterpret_cast<float_t*>(data);
		for (uint32_t pixel = start_pixel; pixel < end_pixel; pixel++) {
			Log::force("Pixel ", pixel, ": {",
				p[pixel * channels + 0], ", ",	// R
				p[pixel * channels + 1], ", ",	// G
				p[pixel * channels + 2],		// B
				channels == 4 ? (", " + std::to_string(p[pixel * channels + 3])) : "", // A
				"}"
			);
		}
	}
	else {
		Log::warning("readback_pixels(): unsupported color byte size: ", color_bytes);
	}
	staging_buffer.unmap();

	// Optionally write the buffer to a .pfm or .png (after conversion) to visually inspect.
}

// getters
VkImage Image::get() const { return image; }
VkFormat Image::get_format() const { return format; }
VkExtent3D Image::get_extent() const { return extent; }
uint32_t Image::get_mip_levels() const { return this->mip_levels; }
uint32_t Image::get_layer_count() const { return this->array_layers; }
VkDeviceSize Image::get_allocation_size() const { return this->allocation_size; }
VkImageCreateFlags Image::get_flags() const { return this->flags; }

VkDeviceMemory Image::get_memory() const {
	if (!vkimage_owned_by_instance) {
		Log::warning("Invalid usage of Image::get_memory(): the underlying VkImage isn't owned by this Image instance; the corresponding memory region is opaque.");
		return VkDeviceMemory(VK_NULL_HANDLE);
	}
	return memory;
}

// helper method for releasing resources
void Image::destroy() {
	if (this->vkimage_owned_by_instance) {
		if (memory != VK_NULL_HANDLE) {
			vkFreeMemory(logical, memory, nullptr);
			memory = VK_NULL_HANDLE;
		}
		if (image != VK_NULL_HANDLE) {
			Log::info("Destroying image (handle: ", image, ")");
			img_list.erase(image);
			img_ID_map.erase(this->unique_ID);
			vkDestroyImage(logical, image, nullptr);
			image = VK_NULL_HANDLE;
		}
	}
}

// helper method to find a suitable memory type
uint32_t Image::find_memory_type(Device& device, VkMemoryPropertyFlags properties, uint32_t type_filter) {
	const auto& mem_properties = device.get_memory_properties();
	for (uint32_t i = 0; i < mem_properties.memoryTypeCount; i++) {
		if ((type_filter & (1 << i)) && (mem_properties.memoryTypes[i].propertyFlags & properties) == properties) {
			return i;
		}
	}
	return UINT32_MAX;
}


// +=================================+   
// | RenderPass                      |
// +=================================+

// a render pass defines the structure and dependencies of graphics rendering operations

// parametric constructor
RenderPass::RenderPass(Device& device, uint32_t multisample_count) : device(&device), logical(device.get_logical()), multisample_count(multisample_count) {}

// move constructor
RenderPass::RenderPass(RenderPass&& other) noexcept {
	move_resources(other);
}

// move assignment constructor
RenderPass& RenderPass::operator=(RenderPass&& other) noexcept {
	if (this != &other) {
		// Release resources held by the current object (if any)
		this->destroy();

		// Move the state from 'other' to 'this'
		move_resources(other);
	}
	return *this;
}

// destructor
RenderPass::~RenderPass() {
	destroy();
}

// adds an attachment description (=owned by this main RenderPass) and returns its index
uint32_t RenderPass::add_attachment(
	AttachmentType type,
	const ColorBlendState& blend_state,
	VkImageLayout initial_layout,
	VkImageLayout final_layout,
	VkAttachmentLoadOp load_op,
	VkAttachmentStoreOp store_op,
	VkAttachmentLoadOp stencil_load_op,
	VkAttachmentStoreOp stencil_store_op,
	VkFormat format
) {

	uint32_t id = static_cast<uint32_t>(attachment_description.size());
	attachment_type.push_back(type);
	blend_states.push_back(blend_state);
	attachment_description.resize(id + 1);
	attachment_description[id] = {};
	attachment_description[id].flags = 0; // or: VK_ATTACHMENT_DESCRIPTION_MAY_ALIAS_BIT
	attachment_description[id].format = format;
	attachment_description[id].initialLayout = initial_layout;
	attachment_description[id].finalLayout = final_layout;
	attachment_description[id].loadOp = load_op;
	attachment_description[id].storeOp = store_op;
	attachment_description[id].stencilLoadOp = stencil_load_op;
	attachment_description[id].stencilStoreOp = stencil_store_op;

	switch (type) {
		case AttachmentType::COLOR_TYPE: {
			attachment_description[id].samples = static_cast<VkSampleCountFlagBits>(multisample_count);
			if (format == VK_FORMAT_UNDEFINED) {
				attachment_description[id].format = VK_FORMAT_R8G8B8A8_SRGB; // default to 8bit RGBA
			}
			color_attachment_flag = true;
			break;
		}
		case AttachmentType::DEPTH_TYPE: {
			attachment_description[id].samples = static_cast<VkSampleCountFlagBits>(multisample_count);
			if (format == VK_FORMAT_UNDEFINED) {
				attachment_description[id].format = device->find_supported_format(DEPTH_FORMAT_CANDIDATES, VK_IMAGE_TILING_OPTIMAL, VK_FORMAT_FEATURE_DEPTH_STENCIL_ATTACHMENT_BIT);
			}
			depth_stencil_flag = true;
			break;
		}
		case AttachmentType::INPUT_TYPE: {
			attachment_description[id].samples = VK_SAMPLE_COUNT_1_BIT; // Input attachments are usually single-sampled
			if (format == VK_FORMAT_UNDEFINED) {
				attachment_description[id].format = device->find_supported_format(INPUT_FORMAT_CANDIDATES, VK_IMAGE_TILING_OPTIMAL, VK_FORMAT_FEATURE_DEPTH_STENCIL_ATTACHMENT_BIT);
			}
			break;
		}
		case AttachmentType::PRESERVE_TYPE: {
			attachment_description[id].samples = VK_SAMPLE_COUNT_1_BIT; // preserve attachments are usually single-sampled
			if (format == VK_FORMAT_UNDEFINED) {
				attachment_description[id].format = device->find_supported_format(PRESERVE_FORMAT_CANDIDATES, VK_IMAGE_TILING_OPTIMAL, VK_FORMAT_FEATURE_DEPTH_STENCIL_ATTACHMENT_BIT);
			}
			break;
		}
		case AttachmentType::RESOLVE_TYPE: {
			attachment_description[id].samples = VK_SAMPLE_COUNT_1_BIT; // resolve attachments are usually single-sampled
			if (format == VK_FORMAT_UNDEFINED) {
				attachment_description[id].format = device->find_supported_format(RESOLVE_FORMAT_CANDIDATES, VK_IMAGE_TILING_OPTIMAL, VK_FORMAT_FEATURE_DEPTH_STENCIL_ATTACHMENT_BIT);
			}
			break;
		}
		default: {
			Log::error("method RenderPass::add_attachment() has been called with invalid RenderAttachment::Type type argument (", type, ")");
		}
	}

	return id;
}

VkSubpassDependency RenderPass::add_subpass_dependency(
	uint32_t source,
	uint32_t destination,
	VkPipelineStageFlags src_stage_mask,
	VkPipelineStageFlags dst_stage_mask,
	VkAccessFlags src_access_mask,
	VkAccessFlags dst_access_mask
) {
	uint32_t id = static_cast<uint32_t>(subpass_dependency.size());
	subpass_dependency.resize(id + 1);
	subpass_dependency[id] = {};
	subpass_dependency[id].srcSubpass = source;
	subpass_dependency[id].dstSubpass = destination;
	subpass_dependency[id].srcStageMask = src_stage_mask;
	subpass_dependency[id].srcAccessMask = src_access_mask;
	subpass_dependency[id].dstStageMask = dst_stage_mask;
	subpass_dependency[id].dstAccessMask = dst_access_mask;
	return subpass_dependency[id];
}

void RenderPass::finalize() {
	VkRenderPassCreateInfo renderpass_create_info = {};
	renderpass_create_info.sType = VK_STRUCTURE_TYPE_RENDER_PASS_CREATE_INFO;
	renderpass_create_info.attachmentCount = static_cast<uint32_t>(attachment_description.size());
	renderpass_create_info.pAttachments = attachment_description.data();
	renderpass_create_info.subpassCount = static_cast<uint32_t>(subpass_description.size());
	renderpass_create_info.pSubpasses = subpass_description.data();
	renderpass_create_info.dependencyCount = static_cast<uint32_t>(subpass_dependency.size());
	renderpass_create_info.pDependencies = subpass_dependency.data();
	if (vkCreateRenderPass(logical, &renderpass_create_info, nullptr, &renderpass) != VK_SUCCESS) {
		Log::error("failed to create render pass!");
	}
	this->finalized = true;
}

// getter functions
VkRenderPass RenderPass::get() const { return renderpass; }
uint32_t RenderPass::get_multisample_count() const { return multisample_count; }
uint32_t RenderPass::get_attachment_count() const { return static_cast<uint32_t>(attachment_description.size()); }
uint32_t RenderPass::get_subpass_count() const { return static_cast<uint32_t>(subpass_description.size()); }
bool RenderPass::has_depth_stencil() const { return depth_stencil_flag; }
bool RenderPass::has_color_attachment() const { return color_attachment_flag; }
const std::vector<VkAttachmentDescription>& RenderPass::get_attachment_descriptions() { return attachment_description; }
const std::vector<ColorBlendState>& RenderPass::get_blend_states() const { return this->blend_states; }
const AttachmentType RenderPass::get_attachment_type(uint32_t index) const { return attachment_type[index]; }

// helper method for releasing resources
void RenderPass::destroy() {
	if (renderpass != nullptr) {
		vkDestroyRenderPass(logical, renderpass, nullptr);
		renderpass = nullptr;
	}
}

// helper method to move resources for the move constructor and move assignment
void RenderPass::move_resources(RenderPass& other) {
	logical = std::exchange(other.logical, VK_NULL_HANDLE);
	device = std::exchange(other.device, nullptr);
	renderpass = std::exchange(other.renderpass, VK_NULL_HANDLE);
	multisample_count = std::move(other.multisample_count);
	attachment_description = std::move(other.attachment_description);
	subpass_description = std::move(other.subpass_description);
}

// +=================================+   
// | SubPass                         |
// +=================================+

// parametric constructor
SubPass::SubPass(RenderPass& renderpass) : renderpass(&renderpass) {}

// add a reference to an attachment from the pool of attachment descriptions owned by the main RenderPass
void SubPass::add_attachment_reference(uint32_t attachment_index) {
	if (finalized) {
		Log::warning("in method SubPass::add_attachment(): this subpass has already been finalized, as it's already been added to a parent RenderPass; hence no more attachments can be added at this point");
		return;
	}
	else {
		switch (renderpass->get_attachment_type(attachment_index)) {
		case AttachmentType::COLOR_TYPE: {
			uint32_t id = static_cast<uint32_t>(color_attachment_reference.size());
			color_attachment_reference.resize(id + 1);
			color_attachment_reference[id].attachment = attachment_index;
			color_attachment_reference[id].layout = VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL;
			break;
		}
		case AttachmentType::DEPTH_TYPE: {
			if (!depth_attachment_reference) {
				depth_attachment_reference = std::make_unique<VkAttachmentReference>();
			}
			depth_attachment_reference->attachment = attachment_index;
			depth_attachment_reference->layout = VK_IMAGE_LAYOUT_DEPTH_STENCIL_ATTACHMENT_OPTIMAL;
			break;
		}
		case AttachmentType::INPUT_TYPE: {
			if (!input_attachment_reference) {
				input_attachment_reference = std::make_unique<std::vector<VkAttachmentReference>>();
			}
			uint32_t id = static_cast<uint32_t>(input_attachment_reference->size());
			input_attachment_reference->resize(id + 1);
			(*input_attachment_reference)[id].attachment = attachment_index;
			(*input_attachment_reference)[id].layout = VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL;
			break;
		}
		case AttachmentType::PRESERVE_TYPE: {
			if (!preserve_attachment_reference) {
				preserve_attachment_reference = std::make_unique<std::vector<uint32_t>>();
			}
			preserve_attachment_reference->push_back(attachment_index);
			break;
		}
		case AttachmentType::RESOLVE_TYPE: {
			if (!resolve_attachment_reference) {
				resolve_attachment_reference = std::make_unique<VkAttachmentReference>();
			}
			resolve_attachment_reference->attachment = attachment_index;
			resolve_attachment_reference->layout = VK_IMAGE_LAYOUT_GENERAL; // 'general' supports all types of device access, unless specified otherwise
			break;
		}
		default: {
			Log::warning("in method SubPass::add_attachment(): RenderAttachment has invalid type; failed to add the attachment to the subpass");
		}
		}
	}
}

// finalize the subpass and add it to the parent RenderPass;
// returns the index of the subpass within the parent RenderPass
uint32_t SubPass::finalize(VkSubpassDescriptionFlags flags, VkPipelineBindPoint bind_point) {
	if (finalized) {
		Log::warning("in method Subpass::finalize() this subpass has already been finalized and added to a parent RenderPass");
		return UINT32_MAX;
	}
	uint32_t id = static_cast<uint32_t>(renderpass->subpass_description.size());
	renderpass->subpass_description.resize(id + 1);
	renderpass->subpass_description[id].flags = flags;
	renderpass->subpass_description[id].pipelineBindPoint = bind_point;

	renderpass->subpass_description[id].inputAttachmentCount = input_attachment_reference ? static_cast<uint32_t>(input_attachment_reference->size()) : 0;
	renderpass->subpass_description[id].pInputAttachments = input_attachment_reference ? input_attachment_reference->data() : nullptr;

	renderpass->subpass_description[id].colorAttachmentCount = static_cast<uint32_t>(color_attachment_reference.size());
	renderpass->subpass_description[id].pColorAttachments = color_attachment_reference.empty() ? nullptr : color_attachment_reference.data();

	renderpass->subpass_description[id].pResolveAttachments = resolve_attachment_reference ? resolve_attachment_reference.get() : nullptr;

	renderpass->subpass_description[id].pDepthStencilAttachment = depth_attachment_reference ? depth_attachment_reference.get() : nullptr;
	renderpass->depth_stencil_flag = depth_attachment_reference ? (depth_attachment_reference->layout != VK_IMAGE_LAYOUT_UNDEFINED) : false;

	renderpass->subpass_description[id].preserveAttachmentCount = preserve_attachment_reference ? static_cast<uint32_t>(preserve_attachment_reference->size()) : 0;
	renderpass->subpass_description[id].pPreserveAttachments = preserve_attachment_reference ? preserve_attachment_reference->data() : nullptr;

	finalized = true;
	this->index = id;
	return id;
}

uint32_t SubPass::get_index() const {
	return this->index;
}

// +=================================+   
// | EventManager                    |
// +=================================+

// Move Constructor
// We explicitly define this to ensure listeners_ is correctly moved.
// The mutex is non-movable/non-copyable, but since it has no state 
// relevant to the listeners, it is safe to be default-initialized 
// in the new object, and the old one remains untouched until destruction.
// The mutex member variable is default-constructed (left unlocked) in the new object.
// The mutex member variable in 'other' is left alone (and will be destroyed safely).
EventManager::EventManager(EventManager&& other) noexcept	:
	listeners(std::move(other.listeners)) { // Move the listeners map
}

// Move Assignment Operator
EventManager& EventManager::operator=(EventManager&& other) noexcept {
	if (this != &other) {
		// No custom cleanup needed for the old 'listeners_' as std::map handles it.
		// Note: Mutexes cannot be moved, so we only move the data structure.
		std::lock_guard<std::mutex> lock_this(mutex); // Lock this object's mutex
		// The mutex is not moved, but we ensure the data transfer is safe.
		listeners = std::move(other.listeners);
	}
	return *this;
}

// Register a callback function for a specific event type
void EventManager::add_listener(EventType type, EventHandler handler) {
	// Protect the map from concurrent modification if registration happens on different threads
	std::lock_guard<std::mutex> lock(mutex);
	listeners[type].push_back(handler);
}

// Dispatch an event to all registered listeners for that event type
void EventManager::dispatch(const SurfaceEvent& event) {
	auto it = listeners.find(event.type);
	if (it != listeners.end()) {
		// Note: Dispatching is intentionally done without a lock for performance, 
		// assuming listeners_ is stable during runtime after initialization.
		for (const auto& handler : it->second) {
			// Execute the handler
			handler(event);
		}
	}
}

#if defined(__ANDROID__)
// This function serves as a hook but does not require complex logic 
// as the NDK's handle_input trampoline handles the actual event routing to dispatch().
void EventManager::setup_android_event_handlers(Surface* surface) {
	// Suppress unused parameter warning since the logic is handled in Surface::handle_input
	(void)surface;
}
#endif

// +=================================+   
// | Surface                         |
// +=================================+

// constructor for Android
#if defined(__ANDROID__)
Surface::Surface(const Instance& instance, uint32_t initial_width, uint32_t initial_height, const char* window_title, android_app* app) :
	instance_handle(instance.get()),
	app(app) {
	if (!instance_handle) {
		Log::warning("Surface creation failed: Provided VkInstance is NULL.");
		return;
	}
	if (!app) {
		Log::warning("Surface creation failed: Provided android_app pointer is NULL.");
		return;
	}

	// Set user data and callbacks to link NDK events back to this instance
	this->app->userData = this;
	this->app->onAppCmd = Surface::handle_cmd;			// use the static trampoline
	this->app->onInputEvent = Surface::handle_input;	// use the static trampoline

	// setup looper/input queue handlers using the 'app' member
	this->event_manager.setup_android_event_handlers(this);

	// note: Surface creation deferred until after window initialization
	Log::debug("Surface constructor (Android): Surface creation deferred until window initialization.");
}

#else
// constructor for Dektop Platforms
// note: please make sure the instance has been created with GLFW extensions and glfwInit() has been called before using this constructor
Surface::Surface(const Instance& instance, uint32_t initial_width, uint32_t initial_height, const char* window_title, GLFWmonitor* monitor, GLFWwindow* share) : instance_handle(instance.get()) {
	if (!instance_handle) {
		Log::warning("Surface creation failed: Provided VkInstance is NULL.");
		return;
	}

	glfwWindowHint(GLFW_CLIENT_API, GLFW_NO_API);	// Tell GLFW not to create an OpenGL context
	glfwWindowHint(GLFW_RESIZABLE, GLFW_TRUE);		// Window Resizing enabled

	this->glfw_window = glfwCreateWindow(initial_width, initial_height, window_title, monitor, share);
	if (!glfw_window) {
		Log::warning("In Surface constructor: Failed to create GLFW window.");
		return;
	}

	// set user pointer first
	glfwSetWindowUserPointer(this->glfw_window, this);

	// Set up GLFW event callbacks 
	glfwSetKeyCallback(this->glfw_window, glfw_key_callback);
	glfwSetFramebufferSizeCallback(this->glfw_window, glfw_resize_callback);
	glfwSetMouseButtonCallback(this->glfw_window, glfw_mouse_button_callback);
	glfwSetCursorPosCallback(this->glfw_window, glfw_mouse_move_callback);
	glfwSetScrollCallback(this->glfw_window, glfw_scroll_callback);
	glfwSetWindowCloseCallback(this->glfw_window, glfw_close_callback);
	glfwSetWindowFocusCallback(this->glfw_window, glfw_focus_callback);

	VkResult result = glfwCreateWindowSurface(instance_handle, this->glfw_window, nullptr, &surface);
	if (result == VK_SUCCESS) {
		Log::info("Surface constructor: GLFW surface created successfully (handle: ", surface, ")");
	}
	else {
		glfwDestroyWindow(this->glfw_window);
		glfw_window = nullptr;
		Log::warning("Surface constructor: Failed to create window surface with GLFW! Result = ", vkresult_to_string(result));
		return;
	}
}
#endif

// Move constructor
Surface::Surface(Surface&& other) noexcept :
	event_manager(std::move(other.event_manager)) {
	instance_handle = std::exchange(other.instance_handle, nullptr);
	surface = std::exchange(other.surface, VK_NULL_HANDLE);

#if defined(__ANDROID__)
	android_window = std::exchange(other.android_window, nullptr); // Transfer Android ownership
	app = std::exchange(other.app, nullptr);
	if (app) {
		app->userData = this;
	}
#else
	glfw_window = std::exchange(other.glfw_window, nullptr); // Transfer GLFW ownership
	if (glfw_window) {
		glfwSetWindowUserPointer(glfw_window, this);
	}
#endif
}

// Move assignment
Surface& Surface::operator=(Surface&& other) noexcept {
	if (this != &other) {
		destroy(); // Clean up *this* object's existing resources (Vulkan surface, window)

		// Transfer all resources from 'other' to *this*
		instance_handle = std::exchange(other.instance_handle, nullptr);
		surface = std::exchange(other.surface, VK_NULL_HANDLE);
		event_manager = std::move(other.event_manager); // Move the EventManager object

		// Android
#if defined(__ANDROID__)
	android_window = std::exchange(other.android_window, nullptr);
	app = std::exchange(other.app, nullptr);
	if (app) {
		app->userData = this;
	}

#else	// Desktop Platform
		glfw_window = std::exchange(other.glfw_window, nullptr);
		// Update the GLFW user pointer on the new window to point to 'this'
		if (glfw_window) {
			glfwSetWindowUserPointer(glfw_window, this);
		}
#endif
	}
	return *this;
}

// Destructor
Surface::~Surface() {
	destroy();
}

// Polls events from the underlying windowing system (GLFW or NDK).
void Surface::poll_events() {
#if defined(__ANDROID__)
	if (!this->app) { return; }
	int ident;
	int events;
	struct android_poll_source* source;

	// ALooper_pollAll timeout=0 makes it non-blocking
	while ((ident = ALooper_pollAll(0, nullptr, &events, (void**)&source)) >= 0) {
		if (source != nullptr) {
			source->process(this->app, source);
		}
	}
#else // desktop platforms (Win32, Linux, MacOS)
	glfwPollEvents(); // Callbacks handle event dispatch
#endif
}

// Dispatch a SurfaceEvent to the internal EventManager
void Surface::dispatch_event(const SurfaceEvent& event) {
	this->event_manager.dispatch(event);
}

// Get a reference to the internal EventManager
EventManager& Surface::get_event_manager() {
	return this->event_manager;
}

// NDK command handler (Android);
// Handles an NDK command received from the static trampoline
#if defined(__ANDROID__)
void Surface::android_command(int32_t cmd) {
	// Send the command as a SurfaceEvent for easy handling in the main application loop
	SurfaceEvent event;
	event.type = EventType::ANDROID_COMMAND;
	event.android_cmd.cmd = cmd;
	this->dispatch_event(event);

	switch (cmd) {
	case APP_CMD_INIT_WINDOW:
		if (app && app->window) {
			this->android_window = this->app->window; // Store the ANativeWindow*
			
			VkAndroidSurfaceCreateInfoKHR create_info = {};
			create_info.sType = VK_STRUCTURE_TYPE_ANDROID_SURFACE_CREATE_INFO_KHR;
			create_info.pNext = nullptr;
			create_info.flags = 0;
			create_info.window = this->android_window;

			VkResult result = vkCreateAndroidSurfaceKHR(instance_handle, &create_info, nullptr, &surface);
			if (result != VK_SUCCESS) {
				Log::warning("Surface::get(): Failed to create Android surface (VkResult=", result, ", ", vkresult_to_string(result), ")");
				return;
			}
			else {
				Log::info("Surface::get(): Android Vulkan surface created successfully (handle: ", surface, ")");
			}
		}
		break;
	case APP_CMD_TERM_WINDOW:
		// Destroy the VkSurfaceKHR before the ANativeWindow* is destroyed by the system
		// The physical window handle is now invalid, but the VkSurfaceKHR must be destroyed first.
		if (surface != VK_NULL_HANDLE) {
			vkDestroySurfaceKHR(instance_handle, surface, nullptr);
			surface = VK_NULL_HANDLE;
			Log::info("[SURFACE] VkSurfaceKHR destroyed in TERM_WINDOW.");
		}
		this->android_window = nullptr;
		break;
	case APP_CMD_WINDOW_RESIZED:
		// Explicitly dispatch a WINDOW_RESIZE event with the new dimensions
		if (app && app->window) {
			SurfaceEvent resize_event;
			resize_event.type = EventType::WINDOW_RESIZE;
			resize_event.resize.width = ANativeWindow_getWidth(app->window);
			resize_event.resize.height = ANativeWindow_getHeight(app->window);
			this->dispatch_event(resize_event);
		}
		break;
	default:
		// All other lifecycle events (e.g., GAINED_FOCUS, LOST_FOCUS) are handled by the initial dispatch_event(ANDROID_COMMAND)
		break;
	}
}
#endif

// Get the underlying VkSurfaceKHR handle
VkSurfaceKHR Surface::get() {
#if defined(__ANDROID__)
	if (!surface) {
		this->android_command(APP_CMD_INIT_WINDOW);
	}
#endif
	return surface;
}

// Check if the surface handle is valid
const bool Surface::is_valid() const {
	return surface != VK_NULL_HANDLE;
}

// Check if a specific queue family on a physical device supports presentation to this surface
const bool Surface::get_physical_device_support(Device& device, QueueFamily queue_family) const {
	if (surface == VK_NULL_HANDLE || device.get_physical() == VK_NULL_HANDLE) {
		Log::warning("Attempted to check surface support with null surface or physical device.");
		return VK_FALSE;
	}
	VkBool32 present_support = VK_FALSE;
	VkResult result;
	switch (queue_family) {
	case QueueFamily::COMPUTE_QUEUE:
		result = vkGetPhysicalDeviceSurfaceSupportKHR(device.get_physical(), device.get_compute_queue_family_index(), surface, &present_support);
		break;
	case QueueFamily::GRAPHICS_QUEUE:
		result = vkGetPhysicalDeviceSurfaceSupportKHR(device.get_physical(), device.get_graphics_queue_family_index(), surface, &present_support);
		break;
	case QueueFamily::TRANSFER_QUEUE:
		result = vkGetPhysicalDeviceSurfaceSupportKHR(device.get_physical(), device.get_transfer_queue_family_index(), surface, &present_support);
		break;
	default:
		result = VK_ERROR_UNKNOWN;
	}
	if (result != VK_SUCCESS) {
		Log::warning("Failed to query physical device surface support, i.e. invalid device or unsupported surface extension (VkResult=", result, ", ", vkresult_to_string(result), ")");
	}
	return bool(present_support);
}

// Get the capabilities of the surface for a specific physical device
VkSurfaceCapabilitiesKHR Surface::get_capabilities(Device& device) const {
	VkSurfaceCapabilitiesKHR capabilities = {};
	if (surface == VK_NULL_HANDLE || device.get_physical() == VK_NULL_HANDLE) {
		Log::warning("Attempted to get surface capabilities with null surface or physical device.");
		return capabilities; // Return empty struct
	}
	VkResult result = vkGetPhysicalDeviceSurfaceCapabilitiesKHR(device.get_physical(), surface, &capabilities);
	if (result != VK_SUCCESS) {
		Log::error("Failed to query physical device surface capabilities (VkResult=", result, ", ", vkresult_to_string(result), ")");
	}
	return capabilities;
}

// Get the supported surface formats for a specific physical device
std::vector<VkSurfaceFormatKHR> Surface::get_formats(Device& device) const {
	std::vector<VkSurfaceFormatKHR> formats;
	if (surface == VK_NULL_HANDLE || device.get_physical() == VK_NULL_HANDLE) {
		Log::warning("Attempted to get surface formats with null surface or physical device.");
		return formats; // Return empty vector
	}
	uint32_t formatCount = 0;
	// Query count first
	VkResult result = vkGetPhysicalDeviceSurfaceFormatsKHR(device.get_physical(), surface, &formatCount, nullptr);
	if (result != VK_SUCCESS || formatCount == 0) {
		Log::warning("Failed to query physical device surface format count or none available (VkResult=", result, ", ", vkresult_to_string(result), ")");
		return formats; // Return empty vector
	}

	formats.resize(formatCount);
	// Query actual formats
	result = vkGetPhysicalDeviceSurfaceFormatsKHR(device.get_physical(), surface, &formatCount, formats.data());
	if (result != VK_SUCCESS) {
		Log::error("Failed to query physical device surface formats (VkResult=", result, ", ", vkresult_to_string(result), ")");
	}
	return formats;
}

// Get the supported presentation modes for a specific physical device
std::vector<VkPresentModeKHR> Surface::get_present_modes(Device& device) const {
	std::vector<VkPresentModeKHR> presentModes;
	if (surface == VK_NULL_HANDLE || device.get_physical() == VK_NULL_HANDLE) {
		Log::warning("Attempted to get surface present modes with null surface or physical device.");
		return presentModes; // Return empty vector
	}
	uint32_t presentModeCount = 0;
	// Query count first
	VkResult result = vkGetPhysicalDeviceSurfacePresentModesKHR(device.get_physical(), surface, &presentModeCount, nullptr);
	if (result != VK_SUCCESS || presentModeCount == 0) {
		Log::warning("Failed to query physical device surface present mode count or none available (VkResult=", result, ", ", vkresult_to_string(result), ")");
		return presentModes; // Return empty vector
	}

	presentModes.resize(presentModeCount);
	// Query actual modes
	result = vkGetPhysicalDeviceSurfacePresentModesKHR(device.get_physical(), surface, &presentModeCount, presentModes.data());
	if (result != VK_SUCCESS) {
		Log::error("Failed to query physical device surface present modes (VkResult=", result, ", ", vkresult_to_string(result), ")");
	}
	return presentModes;
}

// Helper to destroy the surface (called by destructor and move assignment)
void Surface::destroy() {
	// 1. Platform-specific resource cleanup
#if defined(__ANDROID__)
// Unhook Android NDK callbacks and user data
if (this->app) {
	this->app->onAppCmd = nullptr;
	this->app->onInputEvent = nullptr;
	this->app->userData = nullptr;
	this->app = nullptr; // Note: The android_app structure itself is managed externally
	this->android_window = nullptr; // ANativeWindow is destroyed by the system on TERM_WINDOW
}
#else
	if (this->glfw_window) {
		glfwDestroyWindow(this->glfw_window);
		this->glfw_window = nullptr;
	}
#endif

	// 2. Vulkan resource cleanup
	if (surface != VK_NULL_HANDLE && instance_handle != VK_NULL_HANDLE) {
		vkDestroySurfaceKHR(instance_handle, surface, nullptr);
		Log::info("[SURFACE DESTROYED] (handle: ", surface, ")");
	}
	surface = VK_NULL_HANDLE;
}

// --- Static Trampoline Functions (Android NDK Requirement) ---
#if defined(__ANDROID__)
/**
 * @brief Trampoline function to handle NDK application commands (APP_CMD_*) and route them to the Surface instance.
 * @param app Pointer to the android_app structure containing the user data.
 * @param cmd The command ID (e.g., APP_CMD_INIT_WINDOW).
 */
void Surface::handle_cmd(struct android_app* app, int32_t cmd) {
	if (app->userData) {
		// Retrieve the Surface instance from the user data pointer.
		Surface* surface = static_cast<Surface*>(app->userData);
		// Call the non-static member function to process the command.
		surface->android_command(cmd);
	}
}

/**
 * @brief Trampoline function to handle NDK input events (touch, keys, etc.) and route them to the Surface instance.
 * @param app Pointer to the android_app structure.
 * @param event The raw Android NDK input event.
 * @return 1 if the event was handled, 0 otherwise.
 */
int32_t Surface::handle_input(struct android_app* app, AInputEvent* event) {
	if (app->userData) {
		Surface* surface = static_cast<Surface*>(app->userData);
		SurfaceEvent surface_event;

		int32_t event_type = AInputEvent_getType(event);

		if (event_type == AINPUT_EVENT_TYPE_KEY) {
			int32_t key_action = AKeyEvent_getAction(event);

			surface_event.type = (key_action == AKEY_EVENT_ACTION_DOWN) ? EventType::KEY_PRESS : EventType::KEY_RELEASE;
			surface_event.key.key_code = AKeyEvent_getKeyCode(event);
			surface_event.key.scancode = AKeyEvent_getScanCode(event);
			surface_event.key.mods = AKeyEvent_getMetaState(event);

			// Dispatch the event
			surface->dispatch_event(surface_event);
			return 1; // Event handled
		}
		else if (event_type == AINPUT_EVENT_TYPE_MOTION) {
			int32_t motion_action = AMotionEvent_getAction(event);

			// Focus only on primary pointer movements (Pointer Index 0)
			size_t pointer_index = AMotionEvent_getActionIndex(event);
			if (pointer_index == 0) {
				float x = AMotionEvent_getX(event, pointer_index);
				float y = AMotionEvent_getY(event, pointer_index);

				switch (motion_action & AMOTION_EVENT_ACTION_MASK) {
				case AMOTION_EVENT_ACTION_DOWN:
					// Treat initial touch as a mouse button press (left click equivalent)
					surface_event.type = EventType::MOUSE_BUTTON_PRESS;
					surface_event.mouse_button.button = 0; // Left mouse button
					surface_event.mouse_button.mods = AMotionEvent_getMetaState(event);
					surface->dispatch_event(surface_event);
					break;
				case AMOTION_EVENT_ACTION_UP:
					// Treat lift as a mouse button release
					surface_event.type = EventType::MOUSE_BUTTON_RELEASE;
					surface_event.mouse_button.button = 0;
					surface_event.mouse_button.mods = AMotionEvent_getMetaState(event);
					surface->dispatch_event(surface_event);
					break;
				case AMOTION_EVENT_ACTION_MOVE:
					surface_event.type = EventType::MOUSE_MOVE;
					surface_event.mouse_move.xpos = x;
					surface_event.mouse_move.ypos = y;
					surface->dispatch_event(surface_event);
					break;
				default:
					return 0; // Unhandled motion event
				}
			}
			return 1; // Event handled
		}
	}
	return 0; // Event not handled
}
#endif // __ANDROID__

// --- Static Trampoline Functions (GLFW Desktop Requirement) ---
#ifndef __ANDROID__
// Key callback
void Surface::glfw_key_callback(GLFWwindow* window, int key, int scancode, int action, int mods) {
	Surface* surface = static_cast<Surface*>(glfwGetWindowUserPointer(window));
	if (surface) {
		SurfaceEvent event;
		if (action == GLFW_PRESS || action == GLFW_REPEAT) {
			event.type = EventType::KEY_PRESS;
		}
		else if (action == GLFW_RELEASE) {
			event.type = EventType::KEY_RELEASE;
		}
		else {
			return;
		}
		event.key.key_code = key;
		event.key.scancode = scancode;
		event.key.mods = mods;
		surface->dispatch_event(event);
	}
}

// Framebuffer resize callback
void Surface::glfw_resize_callback(GLFWwindow* window, int width, int height) {
	Surface* surface = static_cast<Surface*>(glfwGetWindowUserPointer(window));
	if (surface) {
		SurfaceEvent event;
		event.type = EventType::WINDOW_RESIZE;
		event.resize.width = static_cast<uint32_t>(width);
		event.resize.height = static_cast<uint32_t>(height);
		surface->dispatch_event(event);
	}
}

// Mouse button callback
void Surface::glfw_mouse_button_callback(GLFWwindow* window, int button, int action, int mods) {
	Surface* surface = static_cast<Surface*>(glfwGetWindowUserPointer(window));
	if (surface) {
		SurfaceEvent event;
		event.type = (action == GLFW_PRESS) ? EventType::MOUSE_BUTTON_PRESS : EventType::MOUSE_BUTTON_RELEASE;
		event.mouse_button.button = button;
		event.mouse_button.mods = mods;
		surface->dispatch_event(event);
	}
}

// Cursor position (mouse move) callback
void Surface::glfw_mouse_move_callback(GLFWwindow* window, double xpos, double ypos) {
	Surface* surface = static_cast<Surface*>(glfwGetWindowUserPointer(window));
	if (surface) {
		SurfaceEvent event;
		event.type = EventType::MOUSE_MOVE;
		event.mouse_move.xpos = xpos;
		event.mouse_move.ypos = ypos;
		surface->dispatch_event(event);
	}
}

// Scroll wheel callback
void Surface::glfw_scroll_callback(GLFWwindow* window, double xoffset, double yoffset) {
	Surface* surface = static_cast<Surface*>(glfwGetWindowUserPointer(window));
	if (surface) {
		SurfaceEvent event;
		event.type = EventType::MOUSE_SCROLL;
		event.scroll.xoffset = xoffset;
		event.scroll.yoffset = yoffset;
		surface->dispatch_event(event);
	}
}

// Window close callback. Dispatches a WINDOW_CLOSE event.
void Surface::glfw_close_callback(GLFWwindow* window) {
	Surface* surface = static_cast<Surface*>(glfwGetWindowUserPointer(window));
	if (surface) {
		SurfaceEvent event;
		event.type = EventType::WINDOW_CLOSE;
		// Optionally: use glfwSetWindowShouldClose(window, GLFW_FALSE) here 
		// if the application handles the close request asynchronously.
		surface->dispatch_event(event);
	}
}

// Window focus callback. Dispatches a WINDOW_FOCUS_CHANGE event
void Surface::glfw_focus_callback(GLFWwindow* window, int focused) {
	Surface* surface = static_cast<Surface*>(glfwGetWindowUserPointer(window));
	if (surface) {
		SurfaceEvent event;
		event.type = EventType::WINDOW_FOCUS_CHANGE;
		event.focus.focused = focused;
		surface->dispatch_event(event);
	}
}
#endif // !__ANDROID__

// +=================================+   
// | Fence                           |
// +=================================+

// for synchronization between GPU and CPU

// parametric constructor
Fence::Fence(Device& device, bool signaled) : logical(device.get_logical()) {
	VkFenceCreateInfo create_info = {};
	create_info.sType = VK_STRUCTURE_TYPE_FENCE_CREATE_INFO;
	create_info.pNext = NULL;
	create_info.flags = signaled ? VK_FENCE_CREATE_SIGNALED_BIT : 0;
	vkCreateFence(device.get_logical(), &create_info, nullptr, &fence);
}

// move constructor
Fence::Fence(Fence&& other) noexcept :
	fence(std::exchange(other.fence, VK_NULL_HANDLE)),
	logical(std::exchange(other.logical, VK_NULL_HANDLE)) {
}

// move assignment
Fence& Fence::operator=(Fence&& other) noexcept {
	if (this != &other) {
		logical = std::exchange(other.logical, VK_NULL_HANDLE);
		fence = std::exchange(other.fence, VK_NULL_HANDLE);
	}
	return *this;
}

// destructor
Fence::~Fence() {
	vkDestroyFence(logical, fence, nullptr);
}

// query fence status
bool Fence::signaled(std::string caller_function) const {
	VkResult result = vkGetFenceStatus(logical, fence);
	if (result == VK_SUCCESS) {
		Log::debug("The fence with Vulkan handle ", fence, " has reached the signaled state.");
		return true; // Fence is signaled
	}
	else if (result == VK_NOT_READY) {
		Log::debug("in method Fence::signaled() for calling function ", caller_function, ": fence (handle: ", fence, " is unsignaled or not ready");
		return false; // Fence is not signaled
	}
	else if (result == VK_ERROR_DEVICE_LOST) {
		Log::error("in method Fence::signaled() for calling function ", caller_function, ": device lost! Fence handle: ", fence);
	}
	else {
		Log::warning("in method Fence::signaled() for calling function ", caller_function, ": unknown error(VkResult = ", result, ", ", vkresult_to_string(result), "); Fence handle: ", fence);
	}
	return false; // Fence is not signaled or an error occurred
}

// reset the fence to unsignaled state
VkResult Fence::reset(std::string caller_function) const {
	Log::debug("Fence::reset(): resetting fence (handle: ", fence, ") for calling function ", caller_function);
	return vkResetFences(logical, 1, &fence);
}

// wait for the fence to be signaled
VkResult Fence::wait(std::string caller_function, uint64_t timeout_nanosec) const {
	VkResult result = vkWaitForFences(logical, 1, &fence, VK_TRUE, timeout_nanosec);
	if (result == VK_SUCCESS) {
		Log::debug("Fence::wait(): success! Caller function: ", caller_function, ", Fence wrapper: ", this, ", VkFence Vulkan handle: ", fence, ", max timeout value : ", timeout_nanosec, " nanosec");
		return result; // Fence is signaled
	}
	else if (result == VK_TIMEOUT) {
		Log::warning("in method Fence::wait(): wait for fence (fence handle: ", fence, ", caller function : ", caller_function, ") has timed out!");
	}
	else if (result == VK_ERROR_DEVICE_LOST) {
		Log::error("in method Fence::wait(): device lost! (fence handle: ", fence, ", caller function : ", caller_function, ")");
	}
	else {
		Log::warning("in method Fence::wait(): unknown error (fence handle: ", fence, ", caller function : ", caller_function, ", VkResult = ", result, ", ", vkresult_to_string(result), ")");
	}
	return result;
}

VkFence Fence::get() const { return fence; }


// +=================================+   
// | Semaphore                       |
// +=================================+

// for synchronization on the GPU (between command buffers)

// constructor for a binary semaphore
Semaphore::Semaphore(const Device& device, VkPipelineStageFlagBits2 wait_dst_stage_mask, VkPipelineStageFlagBits2 signal_dst_stage_mask) :
	logical(device.get_logical()),
	wait_dst_stage_mask(wait_dst_stage_mask),
	signal_dst_stage_mask(signal_dst_stage_mask) {

	this->type = VK_SEMAPHORE_TYPE_BINARY;

	VkSemaphoreCreateInfo create_info = {};
	create_info.sType = VK_STRUCTURE_TYPE_SEMAPHORE_CREATE_INFO;
	create_info.flags = 0;

	VkResult result = vkCreateSemaphore(device.get_logical(), &create_info, nullptr, &semaphore);
	if (result != VK_SUCCESS) {
		Log::warning("Semaphore constructor (for binary semaphore) has failed with VkResult = ", result, ", ", vkresult_to_string(result));
	}
	else {
		Log::debug("Semaphore constructor: created binary semaphore ", semaphore);
	}
}

// Constructor for a timeline semaphore
Semaphore::Semaphore(const Device& device, uint64_t initial_value, VkPipelineStageFlagBits2 wait_dst_stage_mask, VkPipelineStageFlagBits2 signal_dst_stage_mask) :
	logical(device.get_logical()),
	wait_dst_stage_mask(wait_dst_stage_mask),
	signal_dst_stage_mask(signal_dst_stage_mask) {

	this->type = VK_SEMAPHORE_TYPE_TIMELINE;

	VkSemaphoreTypeCreateInfo type_create_info = {};
	type_create_info.sType = VK_STRUCTURE_TYPE_SEMAPHORE_TYPE_CREATE_INFO;
	type_create_info.semaphoreType = type;
	type_create_info.initialValue = initial_value;

	VkSemaphoreCreateInfo create_info = {};
	create_info.sType = VK_STRUCTURE_TYPE_SEMAPHORE_CREATE_INFO;
	create_info.pNext = &type_create_info;
	create_info.flags = 0;

	VkResult result = vkCreateSemaphore(device.get_logical(), &create_info, nullptr, &semaphore);
	if (result != VK_SUCCESS) {
		Log::warning("Semaphore constructor (for timeline semaphore) has failed with VkResult = ", result, ", ", vkresult_to_string(result));
	}
	else {
		Log::debug("Semaphore constructor: created timeline semaphore ", semaphore);
	}
}

// destructor
Semaphore::~Semaphore() {
	Log::debug("Semaphore destructor: destroying semaphore ", semaphore);
	vkDestroySemaphore(logical, semaphore, nullptr);
	semaphore = VK_NULL_HANDLE;
}

// move constructor
Semaphore::Semaphore(Semaphore&& other) noexcept :
	semaphore(std::exchange(other.semaphore, VK_NULL_HANDLE)),
	logical(std::exchange(other.logical, VK_NULL_HANDLE)),
	type(other.get_type()) {
}

// move assignment
Semaphore& Semaphore::operator=(Semaphore&& other) noexcept {
	if (this != &other) {
		logical = std::exchange(other.logical, VK_NULL_HANDLE);
		semaphore = std::exchange(other.semaphore, VK_NULL_HANDLE);
		type = other.get_type();
	}
	return *this;
}

// wait for a timeline semaphore to reach the counter value as currently stored in the counter member variable (CPU call)
// note: use with caution! this is a blocking CPU call and defeats the purpose of semaphores (=GPU/GPU synchronization) in most scenarios!
// better approach: use wait semaphore on queue submit;
// this method may still be useful when e.g. the semaphore is expected to already have signaled and to confirm before releasing resources
VkResult Semaphore::wait(uint64_t timeout_nanosec) {
	if (this->type != VK_SEMAPHORE_TYPE_TIMELINE) {
		Log::warning("Semaphore::wait() should only be used with timeline semaphores");
		return VK_ERROR_UNKNOWN;
	}
	VkSemaphoreWaitInfo wait_info = {};
	wait_info.sType = VK_STRUCTURE_TYPE_SEMAPHORE_WAIT_INFO;
	wait_info.pNext = NULL;
	wait_info.flags = VK_SEMAPHORE_WAIT_ANY_BIT;
	wait_info.semaphoreCount = 1;
	wait_info.pSemaphores = &semaphore;
	uint64_t wait_value = this->get_counter_var();
	wait_info.pValues = &wait_value;
	VkResult result = vkWaitSemaphores(logical, &wait_info, timeout_nanosec);
	if (result != VK_SUCCESS) {
		Log::warning("in method Semaphore::wait(): the semaphore (", semaphore, ") has not signaled within the requested max waiting period of ",
			timeout_nanosec, " nano-seconds; VkResult = ", result, "(", vkresult_to_string(result), ")");
	}
	return result;
}

// wait for a timeline semaphore to reach a specific counter value (CPU call)
// note: use with caution! this is a blocking CPU call and defeats the purpose of semaphores (=GPU/GPU synchronization) in most scenarios!
// better approach: use wait semaphore on queue submit;
// this method may still be useful when e.g. the semaphore is expected to already have signaled and to confirm before releasing resources
VkResult Semaphore::wait(uint64_t wait_value, uint64_t timeout_nanosec) {
	if (this->type != VK_SEMAPHORE_TYPE_TIMELINE) {
		Log::warning("Semaphore::wait() should only be used with timeline semaphores");
		return VK_ERROR_UNKNOWN;
	}
	VkSemaphoreWaitInfo wait_info = {};
	wait_info.sType = VK_STRUCTURE_TYPE_SEMAPHORE_WAIT_INFO;
	wait_info.pNext = NULL;
	wait_info.flags = VK_SEMAPHORE_WAIT_ANY_BIT;
	wait_info.semaphoreCount = 1;
	wait_info.pSemaphores = &semaphore;
	wait_info.pValues = &wait_value;
	VkResult result = vkWaitSemaphores(logical, &wait_info, timeout_nanosec);
	if (result != VK_SUCCESS) {
		Log::warning("in method Semaphore::wait(): the semaphore (", semaphore, ") has not signaled within the requested max waiting period of ",
			timeout_nanosec, " nano-seconds; VkResult = ", result, "(", vkresult_to_string(result), ")");
	}
	return result;
}

// query a timeline semaphore counter value (CPU call)
uint64_t Semaphore::get_counter() const {
	if (this->type != VK_SEMAPHORE_TYPE_TIMELINE) {
		Log::warning("method Semaphore::get_counter() should only be used with timeline semaphores!");
		return UINT64_MAX;
	}
	uint64_t value;
	vkGetSemaphoreCounterValue(logical, semaphore, &value);
	return value;
}

// query the current value of the counter (member variable)
uint64_t Semaphore::get_counter_var() const {
	return counter_value.load(std::memory_order_relaxed);
}

// signal a timeline semaphore with a specified value (CPU call)
void Semaphore::signal(uint64_t value) const {
	if (this->type != VK_SEMAPHORE_TYPE_TIMELINE) {
		Log::warning("method Semaphore::signal() should only be used with timeline semaphores!");
		return;
	}
	VkSemaphoreSignalInfo signal_info = {};
	signal_info.sType = VK_STRUCTURE_TYPE_SEMAPHORE_SIGNAL_INFO;
	signal_info.pNext = NULL;
	signal_info.semaphore = semaphore;
	signal_info.value = value;
	vkSignalSemaphore(logical, &signal_info);
}

// flush current counter value (member variable) to semaphore signal (CPU call)
void Semaphore::signal() const {
	if (this->type != VK_SEMAPHORE_TYPE_TIMELINE) {
		Log::warning("method Semaphore::signal() should only be used with timeline semaphores!");
		return;
	}
	VkSemaphoreSignalInfo signal_info = {};
	signal_info.sType = VK_STRUCTURE_TYPE_SEMAPHORE_SIGNAL_INFO;
	signal_info.pNext = NULL;
	signal_info.semaphore = semaphore;
	signal_info.value = counter_value.load();
	vkSignalSemaphore(logical, &signal_info);
}

// setters

// increment counter (member variable (atomic))
uint64_t Semaphore::increment_counter() {
	if (this->type != VK_SEMAPHORE_TYPE_TIMELINE) {
		Log::warning("method Semaphore::increment_counter() should only be used with timeline semaphores!");
		return UINT64_MAX;
	}
	// atomic increment by 1; return new value after increment
	return counter_value.fetch_add(1, std::memory_order_acq_rel) + 1;
}

// set counter member variable atomically to a specific value
void Semaphore::set_counter_var(uint64_t value) {
	if (this->type != VK_SEMAPHORE_TYPE_TIMELINE) {
		Log::warning("method Semaphore::set_counter() should only be used with timeline semaphores!");
		return;
	}
	counter_value.store(value, std::memory_order_relaxed);
}

// getters
VkSemaphore Semaphore::get() const { return semaphore; }
VkSemaphoreType Semaphore::get_type() const { return type; }
const VkSemaphore* Semaphore::get_ptr() const { return &semaphore; }
VkPipelineStageFlags2 Semaphore::get_wait_dst_stage_mask() const { return static_cast<VkPipelineStageFlags2>(wait_dst_stage_mask); }
VkPipelineStageFlags2 Semaphore::get_signal_dst_stage_mask() const { return static_cast<VkPipelineStageFlags2>(signal_dst_stage_mask); }


// +=================================+   
// | Event                           |
// +=================================+

Event::Event(Device& device) : logical(device.get_logical()) {
	// If the VK_KHR_portability_subset extension is enabled, and VkPhysicalDevicePortabilitySubsetFeaturesKHR::events is VK_FALSE,
	// then the implementation does not support events, and vkCreateEvent must not be used !!!
	VkEventCreateInfo create_info = {};
	create_info.sType = VK_STRUCTURE_TYPE_EVENT_CREATE_INFO;
	create_info.pNext = NULL;
	create_info.flags = VK_EVENT_CREATE_DEVICE_ONLY_BIT;
	vkCreateEvent(logical, &create_info, nullptr, &event);
}

// destructor
Event::~Event() {
	vkDestroyEvent(logical, event, nullptr);
}

// move constructor
Event::Event(Event&& other) noexcept :
	event(std::exchange(other.event, VK_NULL_HANDLE)),
	logical(std::exchange(other.logical, VK_NULL_HANDLE)) {
}

// move assignment
Event& Event::operator=(Event&& other) noexcept {
	if (this != &other) {
		logical = std::exchange(other.logical, VK_NULL_HANDLE);
		event = std::exchange(other.event, VK_NULL_HANDLE);
	}
	return *this;
}

void Event::reset() {
	vkResetEvent(logical, event);
}

// set the event to signaled state
void Event::set() const {
	vkSetEvent(logical, event);
}

// query event status
bool Event::signaled() const {
	return vkGetEventStatus(logical, event) == VK_EVENT_SET;
}

// getters
const VkEvent& Event::get() const { return event; }
const VkDependencyInfo& Event::get_dependency_info() const { return dependency_info; }
VkDependencyInfo* Event::get_dependency_info_ptr() { return &dependency_info; }

// +=================================+   
// | CommandPool                     |
// +=================================+

// parametric constructor
CommandPool::CommandPool(Device& device, QueueFamily usage) : logical(device.get_logical()), usage(usage) {

	// setup command pool
	VkCommandPoolCreateInfo create_info = {};
	create_info.sType = VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO;
	create_info.flags = VK_COMMAND_POOL_CREATE_TRANSIENT_BIT | VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT;
	if (usage == QueueFamily::GRAPHICS_QUEUE) {
		create_info.queueFamilyIndex = device.get_graphics_queue_family_index();
	}
	else if (usage == QueueFamily::COMPUTE_QUEUE) {
		create_info.queueFamilyIndex = device.get_compute_queue_family_index();
	}
	else if (usage == QueueFamily::TRANSFER_QUEUE) {
		create_info.queueFamilyIndex = device.get_transfer_queue_family_index();
	}
	else {
		Log::error("in CommandPool constructor: invalid QueueFamily argument!");
	}
	VkResult result = vkCreateCommandPool(logical, &create_info, nullptr, &pool);
	if (result == VK_SUCCESS) {
		Log::info("command pool created (handle: ", pool, ")");
	}
	else {
		Log::error("failed to create command pool (VkResult=", result, ", ", vkresult_to_string(result), ")");
	}
}

// destructor
CommandPool::~CommandPool() {
	if (pool != nullptr) {
		// destroy command pool
		Log::info("CommandPool destructor: destroying command pool with handle ", pool);
		vkDestroyCommandPool(logical, pool, nullptr);
		pool = nullptr;
	}
}

// trim the command pool (release unused memory back to the system)
void CommandPool::trim() const {
	vkTrimCommandPool(logical, pool, NULL);
}

// reset the command pool (release all resources allocated from the pool back to the pool)
VkResult CommandPool::reset(VkCommandPoolResetFlags flags) const {
	return vkResetCommandPool(logical, pool, flags);
}

// getters
VkCommandPool CommandPool::get() const { return pool; }
QueueFamily CommandPool::get_usage() const { return usage; }

// +=================================+   
// | ShaderModule                    |
// +=================================+

// constructor with binary data
ShaderModule::ShaderModule(Device& device, const unsigned char* binary, size_t size_bytes) :
	logical(device.get_logical()) {
	VkShaderModuleCreateInfo shader_module_create_info = {};
	shader_module_create_info.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
	shader_module_create_info.codeSize = size_bytes;
	shader_module_create_info.pCode = reinterpret_cast<const uint32_t*>(binary);

	// free old resource first in case a previous module exists
	if (module != nullptr) {
		Log::info("destroying previous shader module");
		vkDestroyShaderModule(logical, module, nullptr);
	}

	// allocate new module
	VkResult result = vkCreateShaderModule(logical, &shader_module_create_info, nullptr, &module);
	if (result == VK_SUCCESS) {
		Log::debug("new shader module successfully created (handle: ", module, ")");
	}
	else {
		Log::error("failed to create shader module (VkResult = ", result, ", ", vkresult_to_string(result), ")");
	}
}

// Constructor with folder & filename as C-style string literals
ShaderModule::ShaderModule(Device& device, const char* foldername, const char* filename) {
	ShaderModule(device, std::string(foldername), std::string(filename));
}

// constructor with folder & filename as std::string
ShaderModule::ShaderModule(Device& device, const std::string& foldername, const std::string& filename) : logical(device.get_logical()) {

	std::string file_path;
	if (foldername.back() != '/') {
		file_path = foldername + '/' + filename;
	}
	else {
		file_path = foldername + filename;
	}
	long file_size = 0;
	FILE* file = nullptr;
	errno_t err = fopen_s(&file, file_path.c_str(), "rb");
	if (err != 0) {
		// Handle the error (e.g., log it or throw an exception)
		Log::error("Failed to open shader file: ", file_path);
	}
	else {
		Log::debug("reading shader file: ", file_path.c_str());
		fseek(file, 0, SEEK_END);
		file_size = ftell(file);
		fseek(file, 0, SEEK_SET);
		uint8_t* buffer = new uint8_t[file_size];
		fread(buffer, 1, file_size, file);

		VkShaderModuleCreateInfo shader_module_create_info = {};
		shader_module_create_info.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
		shader_module_create_info.codeSize = file_size;
		shader_module_create_info.pCode = reinterpret_cast<uint32_t*>(buffer);

		// free old resource first in case a previous module exists
		if (module != nullptr) {
			Log::info("destroying previous shader module");
			vkDestroyShaderModule(logical, module, nullptr);
		}

		// allocate new module
		VkResult result = vkCreateShaderModule(logical, &shader_module_create_info, nullptr, &module);
		if (result == VK_SUCCESS) {
			Log::debug("new shader module successfully created (handle: ", module, ")");
		}
		else {
			Log::error("failed to create shader module (VkResult = ", result, ", ", vkresult_to_string(result), ")");
		}
		delete[] buffer;
		fclose(file);
	}
}

// move constructor
ShaderModule::ShaderModule(ShaderModule&& other) noexcept {
	this->logical = std::exchange(other.logical, VK_NULL_HANDLE);
	this->module = std::exchange(other.module, VK_NULL_HANDLE);
	if (module != VK_NULL_HANDLE) {
		Log::info("shader module moved (handle: ", module, ")");
	}
}

// move assignment
ShaderModule& ShaderModule::operator=(ShaderModule&& other) noexcept {
	if (this != &other) {
		if (module != nullptr) {
			Log::info("move assignment operation: destroying previous shader module (handle: ", module, ")");
			vkDestroyShaderModule(logical, module, nullptr);
			module = nullptr;
		}
		module = std::exchange(other.module, VK_NULL_HANDLE);
		this->logical = std::exchange(other.logical, VK_NULL_HANDLE);
		if (module != nullptr) {
			Log::info("shader module moved to 'this' (handle: ", module, ")");
		}
	}
	return *this;
}

// destructor
ShaderModule::~ShaderModule() {
	if (module != nullptr) {
		vkDestroyShaderModule(logical, module, nullptr);
	}
}

// getters
const VkShaderModule& ShaderModule::get() const { return module; }



// +=================================+   
// | PushConstants                   |
// +=================================+

// default constructor
PushConstants::PushConstants() {
	data = new char[min_capacity](); // this syntax ensures zero-initialization
}

// constructor with values as std::vector<T>
template<typename T>
PushConstants::PushConstants(const std::vector<T>& values) {
	data = new char[min_capacity]();
	add_values(values);
}

// constructor with values of mixed types as variadic template arguments
template<typename... Args>
PushConstants::PushConstants(Args... args) {
	data = new char[min_capacity]();
	(add_values(args), ...); // fold expression to call the add_values method for each argument
}

// destructor
PushConstants::~PushConstants() {
	if (data != nullptr) {
		delete[] data;
		data = nullptr;
	}
}

// add a new value to the end of the push constants range;
// returns the memory location offset of the new value within the push constants range
template<typename T>
size_t PushConstants::add_values(T value) {

	// --- std430 ALIGNMENT LOGIC ---
	size_t aligned_size = get_std430_alignment<T>();
	size_t padding = (aligned_size - (this->size % aligned_size)) % aligned_size;
	size_t aligned_offset = this->size + padding;

	// The space consumed by T in the block must be at least the required alignment,
	// especially for types like glm::vec3 (size 12, align 16).
	size_t size_increase = sizeof(T);
	if (aligned_size > sizeof(T)) {
		size_increase = aligned_size;
	}
	this->size = aligned_offset + size_increase;

	// Reallocate memory if existing capacity is insufficient.
	if (this->capacity < this->size) {
		this->capacity = size_t(std::max((float_t)min_capacity, ceil(this->size * (1.0f + reserve))));
		this->capacity += 4 - (this->capacity % 4); // ensure capacity is multiple of 4 bytes
		char* new_allocation = new char[this->capacity]();
		if (data != nullptr) {
			memcpy(new_allocation, data, aligned_offset); // copy all previously written data
			delete[] data;
		}
		data = new_allocation;
	}

	// copy value to the end of the data array at the new padded offset
	char* destination = this->data + aligned_offset;

	// std::is_fundamental covers float, int, uint32_t etc
	if constexpr (std::is_fundamental_v<T>) {
		*(T*)destination = value;
	}
	else {
		// use memcpy for aggregate types (structs like glm::vec3/mat4)
		T temp_value = value;
		memcpy(destination, &temp_value, sizeof(T));
	}
	return aligned_offset;
}

// add a new value at the specified offset position of the push constants range;
// overwrites the existing value at that position;
template<typename T>
void PushConstants::add_values(T value, size_t offset) {

	// check if the new value would exceed the total current size.
	if (offset + sizeof(T) > this->size) {
		Log::error("in method PushConstants::add_values(T value, size_t offset): write range exceeds current push constant range size");
		return;
	}

	// copy value to the requested offset
	char* destination = this->data + offset;
	if constexpr (std::is_fundamental_v<T>) {
		*(T*)destination = value;
	}
	else {
		T temp_value = value;
		memcpy(destination, &temp_value, sizeof(T));
	}
}

// add multiple new values to the push constants range as a std::initializer_list;
// returns the byte offset of the last written element within the push constants range
template<typename T>
size_t PushConstants::add_values(std::initializer_list<T> values) {
	size_t current_offset = 0; // will be replaced by return value of add_values
	for (const T& value : values) {
		current_offset = this->add_values(value);
	}
	return current_offset;
}

// add multiple new values to the push constants range as a std::vector<T>;
// returns the memory location byte offset of the new values within the push constants range
template<typename T>
size_t PushConstants::add_values(const std::vector<T>& new_data) {
	size_t current_offset = 0;
	for (const T& value : new_data) {
		current_offset = this->add_values(value);
	}
	return current_offset;
}

// replace all previous constants starting from offset 0;
// return the memory location byte offset of the end of the newly written range
template<typename... Args>
size_t PushConstants::replace_values(size_t begin_offset, Args... args) {
	
	size_t current_offset = begin_offset;

	// Use a fold expression to apply the add_values method for each argument,
	// ensuring the proper offset is passed.
	auto add_and_track_offset = [&](auto&& arg) {
		size_t alignment = get_std430_alignment<decltype(arg)>();
		size_t padding = (alignment - (current_offset % alignment)) % alignment;
		size_t aligned_offset = current_offset + padding;
		
		// write the value at the aligned offset
		this->add_values(arg, aligned_offset);
		
		// advance the offset (stride calculation)
		size_t size_increase = sizeof(arg);
		if (alignment > sizeof(arg)) {
			size_increase = alignment;
		}
		current_offset = aligned_offset + size_increase;
	};
	// apply the update to all arguments
	(add_and_track_offset(args), ...);

	// Ensure the overall size is updated if we wrote past the end
	this->size = std::max(this->size, current_offset);

	return current_offset;
}

// free range by setting its size to zero (this doesn't affect the capacity!)
void PushConstants::free() { this->size = 0; }

// getters
const uint32_t* PushConstants::get_data() const {
	// cast char* to uint32_t* for Vulkan
	return reinterpret_cast<const uint32_t*>(data);
}
size_t PushConstants::get_size() const { return this->size; }
size_t PushConstants::get_total_capacity() const { return this->capacity; }
size_t PushConstants::get_free_capacity() const { return this->capacity - this->size; }

// Helper function to get the std430 alignment for a given type.
// This is the core of the alignment logic.
template<typename T>
constexpr size_t PushConstants::get_std430_alignment() const {
	if constexpr (std::is_same_v<T, float> || std::is_same_v<T, int> || std::is_same_v<T, uint32_t>) {
		return 4;
	}
	else if constexpr (std::is_same_v<T, glm::vec2> || std::is_same_v<T, double_t> || std::is_same_v<T, uint64_t>) {
		return 8;
	}
	else if constexpr (std::is_same_v<T, glm::vec3> || std::is_same_v<T, glm::vec4>) {
		return 16;
	}
	else if constexpr (std::is_same_v<T, glm::mat4>) {
		return 16;
	}
	else {
		if (sizeof(T) <= 4)		return 4;
		else if (sizeof(T) <= 8)		return 8;
		else if (sizeof(T) <= 16)		return 16;
		else if (sizeof(T) <= 32)		return 32;
		else if (sizeof(T) <= 64)		return 64;
		else if (sizeof(T) <= 128)		return 128;
		else if (sizeof(T) <= 256)		return 256;
		else if (sizeof(T) <= 512)		return 512;
		else if (sizeof(T) <= 1024)		return 1024;
		else if (sizeof(T) <= 2048)		return 2048;
		else if (sizeof(T) <= 4096)		return 4096;
		Log::warning("In method PushConstants::get_std430_alignment(): unknown type. Alignment may fail.");
		return sizeof(T);
	}
}

// Helper function to calculate the padded offset for a new value.
template<typename T>
size_t PushConstants::get_padded_offset() {
	size_t alignment = get_std430_alignment<T>();
	// Calculate the padding needed to align the current size
	size_t padding = (alignment - (this->size % alignment)) % alignment;
	return this->size + padding;
}

// +=================================+   
// | Buffer<T>                       |
// +=================================+

// buffer class for vertex data, index data, storage data, uniform data, etc.

// parametric constructor
template<typename T>
Buffer<T>::Buffer(Device& device, BufferType type, uint32_t elements, VkMemoryPropertyFlags memory_property_flags) :
	logical(device.get_logical()),
	memory_property_flags(memory_property_flags),
	elements(elements),
	size_bytes(elements * sizeof(T)) {

	is_host_visible = memory_property_flags & VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT;

	// translate BufferType enum argument
	// note: all usage types can participate in transfer operations by default; this feature may not always be needed (e.g. with uniform buffers), but more likely than not, no relevant performance hit is to be expected anyways
	VkBufferUsageFlags vk_buffer_usage;
	switch (type) {
	case BufferType::VERTEX_BUFFER:   vk_buffer_usage = VK_BUFFER_USAGE_VERTEX_BUFFER_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_TRANSFER_SRC_BIT; break;
	case BufferType::INDEX_BUFFER:    vk_buffer_usage = VK_BUFFER_USAGE_INDEX_BUFFER_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_TRANSFER_SRC_BIT; break;
	case BufferType::STORAGE_BUFFER:  vk_buffer_usage = VK_BUFFER_USAGE_STORAGE_BUFFER_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_TRANSFER_SRC_BIT; break;
	case BufferType::UNIFORM_BUFFER:  vk_buffer_usage = VK_BUFFER_USAGE_UNIFORM_BUFFER_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_TRANSFER_SRC_BIT; break;
	case BufferType::TRANSFER_BUFFER: vk_buffer_usage = VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_TRANSFER_SRC_BIT; break;
	default: Log::error("in method Buffer::Buffer(): invalid BufferType argument: ", type);
	}

	// make sure the buffer size is a multiple of 4
	size_bytes += 4 - (size_bytes % 4);

	// create buffer
	VkBufferCreateInfo buffer_create_info = {};
	buffer_create_info.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO;
	buffer_create_info.size = size_bytes;
	buffer_create_info.usage = vk_buffer_usage;
	buffer_create_info.sharingMode = VK_SHARING_MODE_EXCLUSIVE; // Assuming exclusive access for simplicity

	VkResult result = vkCreateBuffer(logical, &buffer_create_info, nullptr, &buffer);
	if (result == VK_SUCCESS) {
		Log::info("data buffer successfully created (handle: ", buffer, ")");
	}
	else {
		Log::error("failed to create data buffer, VkResult=", result, ", ", vkresult_to_string(result));
	}

	// get buffer memory requirements
	VkMemoryRequirements memory_requirements;
	vkGetBufferMemoryRequirements(logical, buffer, &memory_requirements);

	// find suitable memory type index
	uint32_t type_index = UINT32_MAX;
	Log::info("in Buffer::Buffer() constructor: searching for buffer memory types (requested: ", memory_property_flags, ")");
	const auto& mem_properties = device.get_memory_properties();
	for (uint32_t i = 0; i < mem_properties.memoryTypeCount; i++) {
		Log::debug("memory type ", i, ": ", mem_properties.memoryTypes[i].propertyFlags);
		if ((memory_requirements.memoryTypeBits & (1 << i)) && (mem_properties.memoryTypes[i].propertyFlags & memory_property_flags) == memory_property_flags) {
			type_index = i;
			Log::info("[SUCCESS]");
		}
	}
	if (type_index == UINT32_MAX) {
		Log::error("in Buffer::Buffer() constructor:: no suitable memory type found. Aborting.");
	}

	// allocate memory
	VkMemoryAllocateInfo allocate_info = {};
	allocate_info.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO;
	allocate_info.allocationSize = memory_requirements.size;
	allocate_info.memoryTypeIndex = type_index;
	result = vkAllocateMemory(logical, &allocate_info, nullptr, &memory);
	if (result != VK_SUCCESS) {
		Log::error("in Buffer::Buffer() constructor: failed to allocate buffer memory, VkResult=", result, ", ", vkresult_to_string(result));
	}

	// bind memory to buffer
	result = vkBindBufferMemory(logical, buffer, memory, 0);
	if (result != VK_SUCCESS) {
		Log::error("in Buffer::Buffer() constructor: failed to bind buffer memory, VkResult=", result, ", ", vkresult_to_string(result));
	}
}

// Move constructor
template<typename T>
Buffer<T>::Buffer(Buffer<T>&& other) noexcept
	: buffer(std::exchange(other.buffer, VK_NULL_HANDLE)),
	memory(std::exchange(other.memory, VK_NULL_HANDLE)),
	elements(other.elements),
	logical(std::exchange(other.logical, VK_NULL_HANDLE)),
	size_bytes(other.size_bytes),
	is_host_visible(other.is_host_visible),
	memory_property_flags(other.memory_property_flags) {

	if (buffer != VK_NULL_HANDLE) {
		Log::info("Buffer moved (new owner), handle: ", buffer);
	}
	else {
		Log::warning("Buffer move constructor called, but the 'other' buffer handle is VK_NULL_HANDLE");
	}
}

// Move assignment
template<typename T>
Buffer<T>& Buffer<T>::operator=(Buffer<T>&& other) noexcept {
	if (this != &other) {
		// reference members (device) cannot be reassigned!
		// We must assume that 'this' already has a valid 'device' reference.

		// Release existing resources owned by 'this' object
		if (memory != VK_NULL_HANDLE) {
			vkFreeMemory(logical, memory, nullptr);
			memory = VK_NULL_HANDLE;
		}
		if (buffer != VK_NULL_HANDLE) {
			vkDestroyBuffer(logical, buffer, nullptr);
			buffer = VK_NULL_HANDLE;
		}

		// Transfer ownership of resources from 'other' to 'this'
		this->buffer = other.buffer;
		this->memory = other.memory;
		this->elements = other.elements;
		this->size_bytes = other.size_bytes;
		this->is_host_visible = other.is_host_visible;
		this->memory_property_flags = other.memory_property_flags;

		// Invalidate the other object
		other.buffer = VK_NULL_HANDLE;
		other.memory = VK_NULL_HANDLE;
		other.elements = 0;
		other.size_bytes = 0;

		if (buffer != VK_NULL_HANDLE) {
			Log::info("Buffer move assigned (new owner), handle: ", buffer);
		}
	}
	return *this;
}

// destructor
template<typename T>
Buffer<T>::~Buffer() {
	if (memory != VK_NULL_HANDLE && memory) {
		Log::debug("in Buffer<T> destructor: freeing buffer memory (memory handle: ", memory, ")");
		vkFreeMemory(logical, memory, nullptr);
		memory = VK_NULL_HANDLE;
	}
	if (buffer != VK_NULL_HANDLE && buffer) {
		Log::debug("in Buffer<T> destructor: destroying buffer (buffer handle: ", buffer, ")");
		vkDestroyBuffer(logical, buffer, nullptr);
		buffer = VK_NULL_HANDLE;
	}
}

// copy data elements from a std::vector to a host visible buffer
// (set copied elements to 0 to copy all)
template<typename T>
void Buffer<T>::write(const std::vector<T>& source_vector, uint32_t copied_elements, uint32_t source_offset_elements, uint32_t target_offset_elements) {
	if (!is_host_visible) {
		Log::error("Buffer::write() called on non-host-visible buffer");
	}
	uint32_t vector_elements = source_vector.size();
	uint64_t vector_size_bytes;
	if (copied_elements == 0) {
		vector_size_bytes = (vector_elements - source_offset_elements) * sizeof(T);
	}
	else {
		vector_size_bytes = copied_elements * sizeof(T);
	}
	VkDeviceSize target_offset_bytes = target_offset_elements * sizeof(T);
	if (target_offset_bytes + vector_size_bytes > this->size_bytes) {
		Log::warning("Buffer::write attempting to write past buffer bounds. Clipping copy region size to fit.");
		vector_size_bytes = (this->size_bytes > target_offset_bytes) ? this->size_bytes - target_offset_bytes : 0;
	}
	if (vector_size_bytes == 0) {
		Log::debug("in Buffer<T>::write(): requested copy region has size ", vector_size_bytes, " bytes, i.e.nothing to copy");
		return;
	}
	Log::debug("writing from a vector<T> to buffer ", buffer, " (memory: ", memory, "), ", vector_elements, " vector elements (", vector_size_bytes, " bytes, with ", source_offset_elements, " elements offset in source and ", target_offset_elements, " elements offset in target");
	void* data;
	vkMapMemory(logical, memory, target_offset_bytes, vector_size_bytes, VkMemoryMapFlags(0), &data);
	memcpy(data, source_vector.data() + source_offset_elements, vector_size_bytes);
	vkUnmapMemory(logical, memory);
}

// copy data elements from a std::array to a host visible buffer
template<typename T>
void Buffer<T>::write(const T* source_array, uint32_t copied_elements, uint32_t source_offset_elements, uint32_t target_offset_elements) {
	if (!is_host_visible) {
		Log::error("Buffer::write() called on non-host-visible buffer");
	}
	size_t array_size_bytes = copied_elements * sizeof(T);
	VkDeviceSize target_offset_bytes = target_offset_elements * sizeof(T);
	if (target_offset_bytes + array_size_bytes > this->size_bytes) {
		Log::warning("Buffer::write attempting to write past buffer bounds. Clipping copy region size to fit.");
		array_size_bytes = (this->size_bytes > target_offset_bytes) ? this->size_bytes - target_offset_bytes : 0;
	}
	if (array_size_bytes <= 0) {
		Log::debug("in Buffer<T>::write(): requested copy region has size ", array_size_bytes, " bytes, i.e.nothing to copy");
		return;
	}
	void* data;
	vkMapMemory(logical, memory, target_offset_bytes, array_size_bytes, VkMemoryMapFlags(0), &data);
	memcpy(data, source_array + source_offset_elements, array_size_bytes);
	vkUnmapMemory(logical, memory);
}

// copy data elements from a std::initializer_list to a host visible buffer
template<typename T>
void Buffer<T>::write(const std::initializer_list<T> list, uint32_t target_offset_elements) {
	if (!is_host_visible) {
		Log::error("Buffer::write() called on non-host-visible buffer");
	}
	size_t list_size_bytes = list.size() * sizeof(T);
	VkDeviceSize target_offset_bytes = target_offset_elements * sizeof(T);
	if (target_offset_bytes + list_size_bytes > this->size_bytes) {
		Log::warning("Buffer::write attempting to write past buffer bounds. Clipping copy region size to fit.");
		list_size_bytes = (this->size_bytes > target_offset_bytes) ? this->size_bytes - target_offset_bytes : 0;
	}
	if (list_size_bytes <= 0) {
		Log::debug("in Buffer<T>::write(): requested copy region has size ", list_size_bytes, " bytes, i.e.nothing to copy");
		return;
	}
	Log::debug("writing from a std::initializer_list<T> to buffer ", buffer, " (memory: ", memory, "), ", list.size(), " list elements (", list_size_bytes, " bytes, with ", target_offset_elements, " elements offset in target");
	void* data;
	vkMapMemory(logical, memory, target_offset_bytes, list_size_bytes, VkMemoryMapFlags(0), &data);
	memcpy(data, list.begin(), list_size_bytes);
	vkUnmapMemory(logical, memory);
}

// copy data elements from one host visible buffer to another
// (set copied elements to 0 to copy all);
// the source buffer must be host visible;
// both buffers must be of the same type
template<typename T>
void Buffer<T>::write(const Buffer<T>& sourcebuffer, uint32_t copied_elements, uint32_t source_offset_elements, uint32_t target_offset_elements) {
	if (!is_host_visible) {
		Log::error("Buffer::write() called on non-host-visible buffer");
	}
	size_t source_size_bytes;
	if (copied_elements == 0) {
		source_size_bytes = (sourcebuffer.get_elements() - source_offset_elements) * sizeof(T);
	}
	else {
		source_size_bytes = copied_elements * sizeof(T);
	}
	VkDeviceSize target_offset_bytes = target_offset_elements * sizeof(T);
	VkDeviceSize source_offset_bytes = source_offset_elements * sizeof(T);
	if (target_offset_bytes + source_size_bytes > this->size_bytes) {
		Log::warning("Buffer::write() attempting to write past buffer bounds. Clipping copy region size to fit.");
		source_size_bytes = (this->size_bytes > target_offset_bytes) ? this->size_bytes - target_offset_bytes : 0;
	}
	if (source_size_bytes == 0) {
		Log::debug("in Buffer<T>::write(): requested copy region has size 0, i.e. nothing to copy");
		return;
	}
	void* source = nullptr;
	void* target = nullptr;
	vkMapMemory(logical, sourcebuffer.memory, source_offset_bytes, source_size_bytes, VkMemoryMapFlags(0), &source);
	vkMapMemory(logical, this->memory, target_offset_bytes, source_size_bytes, VkMemoryMapFlags(0), &target);
	memcpy(target, source, source_size_bytes);
	vkUnmapMemory(logical, this->memory);
	vkUnmapMemory(logical, sourcebuffer.memory);
}

// copy data elements from a std::vector to a device-local buffer (via staging buffer)
// (set copied elements to 0 to copy all)
template<typename T>
void Buffer<T>::write(const std::vector<T>& source_vector, uint32_t copied_elements, uint32_t source_offset_elements, uint32_t target_offset_elements, Semaphore* tl_semaphore) {
	if (is_host_visible) {
		this->write(source_vector, copied_elements, source_offset_elements, target_offset_elements);
	}
	else {
		VulkanManager& manager = VulkanManager::get_singleton();
		Task& task = manager.get_compute_task();
		CommandBuffer& cb = task.get_command_buffer();

		// write elements to a staging buffer
		uint32_t elements = copied_elements == 0 ? static_cast<uint32_t>(source_vector.size()) : copied_elements;
		auto& staging_buffer = task.make_buffer<T>(elements, BufferType::TRANSFER_BUFFER, VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT);
		staging_buffer.write(source_vector, elements, source_offset_elements, 0);

		// copy from staging buffer to the device-local buffer
		cb.begin_recording();
		cb.add_buffer_memory_barrier(staging_buffer, VK_ACCESS_2_HOST_WRITE_BIT, VK_ACCESS_2_TRANSFER_READ_BIT, VK_PIPELINE_STAGE_2_HOST_BIT, VK_PIPELINE_STAGE_2_TRANSFER_BIT);
		cb.add_buffer_memory_barrier(*this, VK_ACCESS_2_SHADER_READ_BIT, VK_ACCESS_2_TRANSFER_WRITE_BIT, VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT, VK_PIPELINE_STAGE_2_TRANSFER_BIT);
		cb.record_barriers();
		cb.copy_buffer(staging_buffer, *this);
		cb.add_buffer_memory_barrier(*this, VK_ACCESS_2_TRANSFER_WRITE_BIT, VK_ACCESS_2_SHADER_READ_BIT, VK_PIPELINE_STAGE_2_TRANSFER_BIT, VK_PIPELINE_STAGE_2_VERTEX_SHADER_BIT | VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT);
		cb.record_barriers();
		cb.end_recording();
		task.timeline_sync(*tl_semaphore);
		task.submit();
		task.get_fence().wait();
	}
}

template<typename T>
// copy data elements from a std::array to a device-local buffer (via staging buffer)
void Buffer<T>::write(const T* source_array, uint32_t copied_elements, uint32_t source_offset_elements, uint32_t target_offset_elements, Semaphore* tl_semaphore) {
	if (is_host_visible) {
		this->write(source_array, copied_elements, source_offset_elements, target_offset_elements);
	}
	else {
		VulkanManager manager = VulkanManager::get_singleton();
		Task& task = manager.get_compute_task();
		CommandBuffer& cb = task.get_command_buffer();

		// write elements to a staging buffer
		auto& staging_buffer = task.make_buffer<T>(copied_elements, BufferType::TRANSFER_BUFFER, VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT);
		staging_buffer.write(source_array, copied_elements, source_offset_elements, 0);

		// copy from staging buffer to the device-local buffer
		cb.begin_recording();
		cb.add_buffer_memory_barrier(staging_buffer, VK_ACCESS_2_HOST_WRITE_BIT, VK_ACCESS_2_TRANSFER_READ_BIT, VK_PIPELINE_STAGE_2_HOST_BIT, VK_PIPELINE_STAGE_2_TRANSFER_BIT);
		cb.record_barriers();
		cb.copy_buffer(staging_buffer, *this);
		cb.end_recording();
		task.timeline_sync(*tl_semaphore);
		task.submit();
	}
}

template<typename T>
void* Buffer<T>::map(uint64_t offset, uint64_t size) {
	void* source = nullptr;
	if (!is_host_visible) {
		Log::error("Buffer<T>::map() called on non-host-visible buffer, VkBuffer=", buffer);
	}
	VkResult result = vkMapMemory(logical, this->memory, offset, size, VkMemoryMapFlags(0), &source);
	if (result != VK_SUCCESS) {
		Log::warning("in method Buffer<T>::flush() failed for VkBuffer=", buffer, ": VkResult=", vkresult_to_string(result));
	}
	return source;
}

template<typename T>
void Buffer<T>::unmap() {
	vkUnmapMemory(logical, this->memory);
}

// flush host writes to host memory domain
// this is only necessary if the memory allocation doesn't have the flag VK_MEMORY_PROPERTY_HOST_COHERENT_BIT
// (can be made available to the device memory domain by using a pipeline barrier with the VK_ACCESS_HOST_WRITE_BIT access type flag)
template<typename T>
void Buffer<T>::flush_unmap(uint64_t offset, uint64_t size) {
	if (!is_host_visible) {
		Log::error("Buffer<T>::flush_unmap() called on non-host-visible buffer, VkBuffer=", buffer);
	}
	VkMappedMemoryRange range;
	range.sType = VK_STRUCTURE_TYPE_MAPPED_MEMORY_RANGE;
	range.pNext = NULL;
	range.memory = this->memory;
	range.offset = offset;
	range.size = size;

	VkResult result = vkFlushMappedMemoryRanges(logical, 1, &range);
	if (result != VK_SUCCESS) {
		Log::warning("Buffer<T>::flush_unmap() failed for VkBuffer=", buffer, ": ", vkresult_to_string(result));
	}

	vkUnmapMemory(logical, this->memory);
}

template<typename T>
void Buffer<T>::invalidate(uint64_t offset, uint64_t size) {
	if (!is_host_visible) {
		Log::error("Buffer<T>::flush_invalidate() called on non-host-visible buffer, VkBuffer=", buffer);
	}
	// This function assumes the memory is already mapped.
	VkMappedMemoryRange range;
	range.sType = VK_STRUCTURE_TYPE_MAPPED_MEMORY_RANGE;
	range.pNext = NULL;
	range.memory = this->memory;
	range.offset = offset;
	range.size = size;

	Log::debug("Buffer<T>::invalidate(): invalidating mapped memory range ", this->memory, ", (offset: ", offset, ", size: ", std::min(size, (this->size_bytes - offset)), ")");

	VkResult result = vkInvalidateMappedMemoryRanges(logical, 1, &range);
	if (result != VK_SUCCESS) {
		Log::warning("Buffer<T>::invalidate() failed for VkBuffer=", buffer, ": ", vkresult_to_string(result));
	}
}

// returns a continuous data sequence from a host visible data buffer as a std::vector<T>
// (set read_elements to 0 to read all)
template<typename T>
std::vector<T> Buffer<T>::read(uint32_t read_elements, uint32_t source_offset_elements) {
	if (!is_host_visible) {
		Log::error("Buffer<T>::read() called on non-host-visible buffer");
	}
	uint32_t source_elements;
	if (read_elements == 0) {
		source_elements = this->elements - source_offset_elements;

	}
	else {
		source_elements = read_elements;
	}
	if (source_offset_elements + source_elements > this->elements) {
		Log::warning("Buffer::read() attempting to read past buffer bounds). Clipping read region size to fit.");
		source_elements = (this->elements > source_offset_elements) ? this->elements - source_offset_elements : 0;
	}
	VkDeviceSize source_size_bytes = source_elements * sizeof(T);
	VkDeviceSize source_offset_bytes = source_offset_elements * sizeof(T);
	std::vector<T> result(source_elements);
	if (source_size_bytes == 0) {
		Log::debug("in Buffer<T>::read(): requested region has size 0; returning an empty vector");
		return result;
	}
	void* data;
	vkMapMemory(logical, memory, source_offset_bytes, source_size_bytes, VkMemoryMapFlags(0), &data);
	memcpy(result.data(), data, source_size_bytes);
	vkUnmapMemory(logical, memory);
	return result;
}

// returns a single element from a host visible data buffer
template<typename T>
T Buffer<T>::read_element(uint32_t element_index) const {
	if (!is_host_visible) {
		Log::error("Buffer::read_element(uint32_t element_index) called on non-host-visible buffer");
	}
	if (element_index >= this->elements) {
		Log::error("in method Buffer::get(): element index ", element_index, " is out of bounds (allowed indices: 0-", this->elements - 1, ")");
	}
	void* data = nullptr;
	VkResult result = vkMapMemory(logical, memory, element_index * sizeof(T), sizeof(T), VkMemoryMapFlags(0), &data);
	if (result != VK_SUCCESS) {
		Log::error("in method Buffer<T>::get(uint32_t element_index): failed to map buffer memory (VkResult = ", result, ", ", vkresult_to_string(result), ")");
	}
	T element;
	memcpy(&element, data, sizeof(T));
	vkUnmapMemory(logical, memory);
	return element;
}

// assigns a single element of a host visible data buffer
template<typename T>
void Buffer<T>::write_element(uint32_t element_index, T value) {
	if (!is_host_visible) {
		Log::error("method Buffer<T>::set() called on non-host-visible buffer.");
	}
	if (element_index >= this->elements) {
		Log::error("in method Buffer::set(): element index ", element_index, " is out of bounds (allowed indices: 0-", this->elements - 1, ")");
	}
	void* data = nullptr;
	VkResult result = vkMapMemory(logical, memory, element_index * sizeof(T), sizeof(T), VkMemoryMapFlags(0), &data);
	if (result != VK_SUCCESS) {
		Log::error("in method Buffer<T>::set(uint32_t element_index, T value): failed to map buffer memory (VkResult = ", result, ", ", vkresult_to_string(result), ")");
	}
	memcpy(data, &value, sizeof(T));
	vkUnmapMemory(logical, memory);
}

// assigns the same value to continuous sequence of buffer elements
// (set write_elements to 0 to assign all)
template<typename T>
void Buffer<T>::set_all(T value, uint32_t offset_elements, uint32_t write_elements) {
	if (!is_host_visible) {
		Log::error("method Buffer<T>::set_all() called on non-host-visible buffer.");
	}
	size_t element_size = sizeof(T);
	if (offset_elements >= this->elements) {
		Log::error("in method Buffer::set_all(): invalid offset argument; value is ", offset_elements, " but the buffer only has ",
			this->elements, " elements, i.e. the max allowed offset argument is ", this->elements - 1);
	}
	if (write_elements > this->elements - offset_elements) {
		Log::error("in method Buffer::set_all(): invalid write_elements argument; value is ", write_elements, " for a buffer of ",
			this->elements, " elements, i.e. only ", this->elements - offset_elements, " elements can be written beyond the desired offset of ", offset_elements, " elements)");
	}
	VkDeviceSize offset_bytes = offset_elements * element_size;
	VkDeviceSize write_bytes = write_elements == 0 ? (this->elements - offset_elements) * element_size : write_elements * element_size;
	void* data;
	vkMapMemory(logical, memory, offset_bytes, write_bytes, VkMemoryMapFlags(0), &data);
	for (size_t offset = 0; offset < write_bytes; offset += element_size) {
		memcpy((T*)data + offset, &value, element_size);
	}
	vkUnmapMemory(logical, memory);
}

// getters
template<typename T> uint32_t Buffer<T>::get_elements() const { return this->elements; }
template<typename T> uint64_t Buffer<T>::get_size_bytes() const { return size_bytes; }
template<typename T> VkDeviceMemory Buffer<T>::get_memory() const { return memory; }
template<typename T> VkBuffer Buffer<T>::get() const { return buffer; }
template<typename T> VkMemoryPropertyFlags Buffer<T>::get_memory_property_flags() const { return memory_property_flags; }
template<typename T> bool Buffer<T>::host_visible() const { return is_host_visible; }

// +=================================+   
// | Sampler                         |
// +=================================+

// Sampler class for texture sampling

// constructor
Sampler::Sampler(
	Device& device,
	VkFilter magFilter,
	VkFilter minFilter,
	VkSamplerAddressMode address_mode_U,
	VkSamplerAddressMode address_mode_V,
	VkSamplerMipmapMode mipmapMode,
	uint32_t mip_levels,
	float_t max_anisotropy_level
) : logical(device.get_logical()) {
	sampler_create_info.sType = VK_STRUCTURE_TYPE_SAMPLER_CREATE_INFO;
	sampler_create_info.pNext = nullptr;
	sampler_create_info.magFilter = magFilter;
	sampler_create_info.minFilter = minFilter;
	sampler_create_info.addressModeU = address_mode_U;
	sampler_create_info.addressModeV = address_mode_V;
	sampler_create_info.addressModeW = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE; // hard-coded default (change if needed)
	sampler_create_info.anisotropyEnable = max_anisotropy_level > 0.0f;
	sampler_create_info.maxAnisotropy = std::min(max_anisotropy_level, device.get_properties2().properties.limits.maxSamplerAnisotropy);
	sampler_create_info.borderColor = VK_BORDER_COLOR_INT_OPAQUE_BLACK;
	sampler_create_info.unnormalizedCoordinates = VK_FALSE;
	sampler_create_info.compareEnable = VK_FALSE;
	sampler_create_info.compareOp = VK_COMPARE_OP_ALWAYS;
	sampler_create_info.mipmapMode = mipmapMode;
	sampler_create_info.minLod = 0.0f;
	sampler_create_info.maxLod = static_cast<float_t>(mip_levels > 0 ? mip_levels - 1 : 0);
	sampler_create_info.mipLodBias = 0.0f;

	if (vkCreateSampler(logical, &sampler_create_info, nullptr, &sampler) != VK_SUCCESS) {
		Log::error("failed to create texture sampler!");
	}
}

// destructor
Sampler::~Sampler() {
	if (sampler != nullptr) {
		vkDestroySampler(logical, sampler, nullptr);
		Log::info("destroyed image sampler (handle: ", sampler, ")");
		sampler = nullptr;
	}
}

// getters
const VkSampler Sampler::get() const { return sampler; }
const VkSampler* Sampler::get_ptr() const { return &sampler; }

// +=================================+   
// | Texture                         |
// +=================================+

// Constructor
Texture::Texture(
	Device& device,
	const std::string& filepath,
	VkFormat format, // output format
	Semaphore* tl_semaphore,
	float_t max_anisotropy_level,
	VkSamplerAddressMode sampler_address_mode_U,
	VkSamplerAddressMode sampler_address_mode_V,
	TextureType type, // source type
	int force_mip_levels) : device(&device) {

	std::filesystem::path project_root = get_executable_directory() / "..";
	std::filesystem::path full_filepath = project_root / filepath;
	std::filesystem::path resolved_path = std::filesystem::absolute(full_filepath);
	std::string full_filepath_str = resolved_path.generic_string();

	int src_width, src_height;
	int src_channels; // color channels per pixel in the result from STBI or TinyEXR
	size_t out_pixel_bytes = get_format_bytes_per_pixel(format);
	uint32_t out_channels = 0; // desired color channels per pixel in the output format
	VkFormat out_format = format;
	switch(out_pixel_bytes) {
	case 3: out_channels = 3; break;
	case 4: out_channels = 4; break;
	case 16:out_channels = 4; break;
	default:
		Log::warning("In Texture constructor: requested output format is ", out_pixel_bytes * 8, " bits per pixel. Only 24bit or 32bit (RGB/RGBA LDR) or 128bit (RGBA HDR) formats are supported.");
		if (out_pixel_bytes > 4) {
			Log::warning("Trying to use RGBA with 32bits (float) per pixel instead (VK_FORMAT_R32G32B32A32_SFLOAT)");
			out_format = VK_FORMAT_R32G32B32A32_SFLOAT;
			out_channels = 4;
			out_pixel_bytes = 16;
		}
		else {
			Log::warning("Trying to use RGBA with 8bits (uint8_t) per pixel instead (VK_FORMAT_R8G8B8A8_SRGB)");
			out_format = VK_FORMAT_R8G8B8A8_SRGB;
			out_channels = 4;
			out_pixel_bytes = 4;
		}
	}
	uint8_t* src_data_ldr8u = nullptr;
	float_t* src_data_hdr32f = nullptr;
	bool is_cubemap = false;
	uint32_t array_layers = 1;
	VkImageCreateFlags flags = 0;
	VkImageUsageFlags image_usage = VK_IMAGE_USAGE_SAMPLED_BIT | VK_IMAGE_USAGE_TRANSFER_DST_BIT | VK_IMAGE_USAGE_TRANSFER_SRC_BIT | VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT;
	VkImageAspectFlags aspect_mask = VK_IMAGE_ASPECT_COLOR_BIT;
	VkImageViewType image_view_type = VK_IMAGE_VIEW_TYPE_2D;
	uint32_t mip_levels = 1;

	VulkanManager& manager = VulkanManager::get_singleton();

	Log::info("Texture Constructor: Loading texture from file: ", full_filepath_str, " ...");

	// Determine loading parameters based on texture type
	switch (type) {
	case TextureType::SRGB_TEXTYPE:
	case TextureType::LINEAR_TEXTYPE: {
		stbi_set_flip_vertically_on_load(true);
		if (out_channels == 3) {
			src_data_ldr8u = stbi_load(full_filepath_str.c_str(), &src_width, &src_height, &src_channels, STBI_rgb);
			if (!src_data_ldr8u) { Log::warning("failed to load SRGB_TEXTYPE or LINEAR_TEXTYPE texture image: ", full_filepath_str, " via STBI. Reason: ", stbi_failure_reason()); return; }
			if (src_channels == 4) {
				Log::warning("Source file has 4 channels per pixel, but the desired output format only has 3 --> alpha channel will be dropped");
			}
		}
		else if (out_channels == 4) {
			src_data_ldr8u = stbi_load(full_filepath_str.c_str(), &src_width, &src_height, &src_channels, STBI_rgb_alpha);
			if (!src_data_ldr8u) { Log::warning("failed to load texture image: ", full_filepath_str, ". Reason: ", stbi_failure_reason()); return; }
			if (src_channels < 4) {
				Log::warning("Source file has ", src_channels, " channels per pixel, but the desired output format has 4 --> excess channels in result pixels are padded");
			}
		}
		else {
			Log::warning("Unsupported format for SRGB_TEXTYPE or LINEAR_TEXTYPE texture. Expected 8-bit RGB or RGBA format.");
		}
		mip_levels = force_mip_levels >= 0 ? force_mip_levels : static_cast<uint32_t>(std::floor(std::log2(std::max(src_width, src_height)))) + 1;
		break;
	}
	case TextureType::RGBA_HDR_TEXTYPE: {
		mip_levels = force_mip_levels >= 0 ? force_mip_levels : 1; // typically no mipmaps for equirectangular cubemaps
		if (out_format != VK_FORMAT_R32G32B32A32_SFLOAT) {
			Log::warning("Unsupported format for RGBA_HDR_TEXTYPE texture. Expected R32G32B32A32_SFLOAT -> changing it automatically.");
			out_format = VK_FORMAT_R32G32B32A32_SFLOAT;
		}
		const char* err = nullptr;
		int result = LoadEXR(&src_data_hdr32f, &src_width, &src_height, full_filepath_str.c_str(), &err);
		if (result != TINYEXR_SUCCESS) {
			Log::warning("In Texture constructor: failed to load RGBA_HDR_TEXTYPE texture image via TinyEXR. Result: ", err);
			FreeEXRErrorMessage(err);
		}
		mip_levels = force_mip_levels >= 0 ? force_mip_levels : static_cast<uint32_t>(std::floor(std::log2(std::max(src_width, src_height)))) + 1;
		break;
	}
	case TextureType::BRDF_LUT_TEXTYPE: {
		mip_levels = force_mip_levels >= 0 ? force_mip_levels : 1; // typically no mipmaps for LUT
		// 1. Make sure the output format is VK_FORMAT_R32G32B32A32_SFLOAT
		if (out_format != VK_FORMAT_R32G32B32A32_SFLOAT) {
			Log::warning("In Texture constructor for BRDF_LUT_TEXTYPE: output format must be VK_FORMAT_R32G32B32A32_SFLOAT -> changing it automatically");
			out_format = VK_FORMAT_R32G32B32A32_SFLOAT;
		}
		// 2. try to load via STBI
		src_data_hdr32f = stbi_loadf(full_filepath_str.c_str(), &src_width, &src_height, &src_channels, STBI_rgb_alpha);
		if (!src_data_hdr32f) {
			// 3. if STBI fails: try TinyEXR
			Log::debug("failed to load BRDF LUT image via STBI: ", full_filepath_str, ". Reason: ", stbi_failure_reason(), ". Next: trying to load it via TinyEXR.");
			const char* err = nullptr;
			int result = LoadEXR(&src_data_hdr32f, &src_width, &src_height, full_filepath_str.c_str(), &err);
			if (result != TINYEXR_SUCCESS) {
				Log::warning("In Texture constructor: failed to load BRDF_LUT_TEXTYPE texture image via TinyEXR. Result: ", err);
				FreeEXRErrorMessage(err);
			}
		}
		break;
	}
	case TextureType::EQUIRECTANGULAR_HDR_TEXTYPE: {
		mip_levels = force_mip_levels >= 0 ? force_mip_levels : 1; // typically no mipmaps for equirectangular cubemaps
		if (out_format != VK_FORMAT_R32G32B32A32_SFLOAT) {
			Log::warning("Unsupported format for EQUIRECTANGULAR_HDR_TEXTYPE texture. Expected R32G32B32A32_SFLOAT.");
		}
		const char* err = nullptr;
		int result = LoadEXR(&src_data_hdr32f, &src_width, &src_height, full_filepath_str.c_str(), &err);
		if (result != TINYEXR_SUCCESS) {
			Log::warning("In Texture constructor: failed to load EQUIRECTANCULAR_HDR_TEXTYPE texture image via TinyEXR. Result: ", err);
			FreeEXRErrorMessage(err);
		}
		break;
	}
	case TextureType::EQUIRECTANGULAR_TEXTYPE: {
		stbi_set_flip_vertically_on_load(true); // Equirectangular maps usually need flipping
		if (out_pixel_bytes > 4) {
			Log::warning("In Texture constructor: EQUIRECTANGULAR_TEXTYPE (LDR) doesn't support an output format with >4 bytes per pixel"); return;
		}
		if (out_channels == 3) {
			src_data_ldr8u = stbi_load(full_filepath_str.c_str(), &src_width, &src_height, &src_channels, STBI_rgb);
			if (!src_data_ldr8u) { Log::warning("failed to load EQUIRECTANGULAR_TEXTYPE texture image: ", full_filepath_str, ". Reason: ", stbi_failure_reason()); return; }
			if (src_channels == 4) {
				Log::warning("Source file has 4 channels per pixel, but the desired output format only has 3 --> dropping the alpha channel");
			}
		}
		else {
			src_data_ldr8u = stbi_load(full_filepath_str.c_str(), &src_width, &src_height, &src_channels, STBI_rgb_alpha);
			if (!src_data_ldr8u) { Log::warning("failed to load texture image: ", full_filepath_str, ". Reason: ", stbi_failure_reason()); return; }
		}
		stbi_set_flip_vertically_on_load(false); // Reset for other loads
		mip_levels = force_mip_levels >= 0 ? force_mip_levels : 1; // typically no mipmaps for equirectangular cubemaps
		break;
	}
	case TextureType::CUBEMAP_TEXTYPE:
	case TextureType::CUBEMAP_HDR_TEXTYPE:
	case TextureType::IRRADIANCE_CUBEMAP_TEXTYPE:
	case TextureType::PREFILTERED_CUBEMAP_TEXTYPE: {
		// These types are render targets for IBL/equirectangular conversion and MUST have COLOR_ATTACHMENT_BIT
		image_usage |= VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT;
		is_cubemap = true;
		array_layers = CUBEMAP_FACE_COUNT;
		flags |= VK_IMAGE_CREATE_CUBE_COMPATIBLE_BIT;
		image_view_type = VK_IMAGE_VIEW_TYPE_CUBE;
		mip_levels = force_mip_levels >= 0 ? force_mip_levels : 1;

		// Calculate full mip chain for PREFILTERED map if not forced.
		if (type == TextureType::PREFILTERED_CUBEMAP_TEXTYPE && mip_levels <= 1) {
			mip_levels = static_cast<uint32_t>(std::floor(std::log2(std::max(src_width, src_height)))) + 1;
			Log::debug("PREFILTERED_CUBEMAP_TEXTYPE mip_levels automatically set to ", mip_levels);
		}
		// Handle cubemap loading (6 faces)
		const char* face_suffixes[6] = { "_right", "_left", "_top", "_bottom", "_front", "_back" };
		// Could also use: {"_px", "_nx", "_py", "_ny", "_pz", "_nz"}

		std::string base_path = full_filepath_str.substr(0, full_filepath_str.find_last_of('.'));
		std::string extension = full_filepath_str.substr(full_filepath_str.find_last_of('.'));

		// Load first face to get dimensions
		std::string first_face_path = base_path + face_suffixes[0] + extension;
		
		if (out_pixel_bytes > 4) {
			// HDR source format expected
			const char* err = nullptr;
			int result = LoadEXR(&src_data_hdr32f, &src_width, &src_height, full_filepath_str.c_str(), &err);
			if (result != TINYEXR_SUCCESS) {
				Log::warning("In Texture constructor: failed to load cubemap HDR texture image via TinyEXR. Result: ", err);
				FreeEXRErrorMessage(err);
			}
		}
		else {
			// LDR source format expected
			stbi_set_flip_vertically_on_load(false); // Cubemaps typically don't flip
			if (out_channels == 3) {
				src_data_ldr8u = stbi_load(first_face_path.c_str(), &src_width, &src_height, &src_channels, STBI_rgb);
				if (!src_data_ldr8u) { Log::warning("failed to load cubemap LDR texture image: ", first_face_path, ". Reason: ", stbi_failure_reason()); return; }
				if (src_channels == 4) {
					Log::warning("Source file has 4 channels per pixel, but the desired output format only has 3 --> dropping the alpha channel");
				}
			}
			else {// out_channels == 4
				src_data_ldr8u = stbi_load(first_face_path.c_str(), &src_width, &src_height, &src_channels, STBI_rgb_alpha);
				if (!src_data_ldr8u) { Log::warning("failed to load texture image: ", first_face_path, ". Reason: ", stbi_failure_reason()); return; }
			}
		}
		// We'll load all 6 faces below
		break;
	}
	case TextureType::DEPTH_STENCIL_TEXTYPE: {
		image_usage |= VK_IMAGE_USAGE_DEPTH_STENCIL_ATTACHMENT_BIT;
		aspect_mask = VK_IMAGE_ASPECT_DEPTH_BIT;
		mip_levels = force_mip_levels >= 0 ? force_mip_levels : 1;
		if (out_pixel_bytes > 4) {
			// HDR source format expected
			const char* err = nullptr;
			int result = LoadEXR(&src_data_hdr32f, &src_width, &src_height, full_filepath_str.c_str(), &err);
			if (result != TINYEXR_SUCCESS) {
				Log::warning("In Texture constructor: failed to load DEPTH_STENCIL_TEXTYPE texture image via TinyEXR (assuming HDR source). Result: ", err);
				FreeEXRErrorMessage(err);
			}
		}
		else {
			// LDR source format expexted
			stbi_set_flip_vertically_on_load(false);
			// try without alpha channel first
			if (out_channels == 3) {
				src_data_ldr8u = stbi_load(full_filepath_str.c_str(), &src_width, &src_height, &src_channels, STBI_rgb);
				if (!src_data_ldr8u) { Log::warning("failed to load DEPTH_STENCIL_TEXTYPE texture image via STBI (assuming LDR, as RGB without alpha channel): ", full_filepath_str, ". Reason: ", stbi_failure_reason()); }
			}
			else {
				src_data_ldr8u = stbi_load(full_filepath_str.c_str(), &src_width, &src_height, &src_channels, STBI_rgb_alpha);
				if (!src_data_ldr8u) { Log::warning("failed to load DEPTH_STENCIL_TEXTYPE texture image via STBI (assuming LDR / RGBA): ", full_filepath_str, ". Reason: ", stbi_failure_reason()); }
				out_channels = 4;
				out_format = VK_FORMAT_R8G8B8A8_SRGB;
			}
		}
		break;
	}
	} // end of switch statement

	// Log Success
	if (src_data_ldr8u) {
		Log::debug("loaded LDR texture to host memory (uint8_t* src_data_ldr8u = ", src_data_ldr8u, "): ", full_filepath_str, " (", src_width, "x", src_height, " pixels, ",
			array_layers, " layer(s), ", mip_levels, " mip(s))");
	}
	if (src_data_hdr32f) {
		Log::debug("loaded HDR texture to host memory (float_t* src_data_hdr32f = ", src_data_hdr32f, "): ", full_filepath_str, " (", src_width, "x", src_height, " pixels, ",
			array_layers, " layer(s), ", mip_levels, " mip(s))");
	}

	// Create sampler
	VkSamplerAddressMode w_mode = (is_cubemap) ? VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE : sampler_address_mode_U;
	sampler = std::make_unique<Sampler>(
		device,
		VK_FILTER_LINEAR,
		VK_FILTER_LINEAR,
		sampler_address_mode_U,
		sampler_address_mode_V,
		VK_SAMPLER_MIPMAP_MODE_LINEAR,
		mip_levels,
		max_anisotropy_level
	);

	// Create image
	this->image = std::make_unique<Image>(
		device,
		VK_IMAGE_TYPE_2D,
		format,
		VkExtent3D(src_width, src_height, 1),
		mip_levels,
		array_layers,
		VK_SAMPLE_COUNT_1_BIT,
		VK_IMAGE_TILING_OPTIMAL,
		image_usage,
		VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT,
		VK_IMAGE_LAYOUT_UNDEFINED,
		flags
	);

	// Upload pixel data
	Task& task = manager.get_graphics_task();
	CommandBuffer& cb = task.get_command_buffer();
	const uint32_t required_byte_alignment = 256u;
	uint32_t row_byte_size = src_width * out_pixel_bytes; // UNPADDED row size
	uint32_t padded_row_byte_size = ((row_byte_size + required_byte_alignment - 1) / required_byte_alignment) * required_byte_alignment;
	VkDeviceSize layer_padded_size = padded_row_byte_size * src_height;
	VkDeviceSize total_padded_size = layer_padded_size * array_layers;



	Log::debug("Preparing to upload texture data to GPU (pixel bytes: ", out_pixel_bytes, ", (padded) layer size : ", layer_padded_size, ", (padded) total size : ", total_padded_size, " bytes)");

	// Create staging buffer and map its memory to 'data'
	Buffer<uint8_t>& staging_buffer = task.make_buffer<uint8_t>(total_padded_size, BufferType::TRANSFER_BUFFER, VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT);
	void* data = staging_buffer.map(0, total_padded_size);

	// === CUBEMAPS: LOAD INDIVIDUAL FACES TO MAPPED MEMORY OF THE STAGING BUFFER ===
	if (is_cubemap) {

		// Load and copy all 6 faces
		std::string base_path = full_filepath_str.substr(0, full_filepath_str.find_last_of('.'));
		std::string extension = full_filepath_str.substr(full_filepath_str.find_last_of('.'));
		const char* face_suffixes[6] = { "_right", "_left", "_top", "_bottom", "_front", "_back" };

		// === LDR cubemaps ===
		if (src_data_ldr8u) {
			// Pointer for copying layers
			uint8_t* dst_layer_start = static_cast<uint8_t*>(data);

			for (int i = 0; i < CUBEMAP_FACE_COUNT; i++) {
				uint8_t* face_pixels;
				if (i == 0) {
					face_pixels = src_data_ldr8u; // Already loaded first face
				}
				else {
					std::string face_path = base_path + face_suffixes[i] + extension;
					if (out_channels == 3) {
						face_pixels = stbi_load(face_path.c_str(), &src_width, &src_height, &src_channels, STBI_rgb);
					}
					else {// out_channels == 4
						face_pixels = stbi_load(face_path.c_str(), &src_width, &src_height, &src_channels, STBI_rgb_alpha);
					}
					if (!face_pixels) {
						Log::warning("failed to load cubemap face[", i, "]: ", face_path, ". Reason : ", stbi_failure_reason());
						continue;
					}
				}

				// Set the destination start for the current face
				uint8_t* dst_row = dst_layer_start + (i * padded_row_byte_size * src_height);
				const uint8_t* src_row = static_cast<const uint8_t*>(face_pixels);

				if (row_byte_size != padded_row_byte_size) {
					// Copy row by row with padding for the current face
					for (uint32_t y = 0; y < src_height; ++y) {
						memcpy(dst_row, src_row, row_byte_size);

						// Advance pointers by the PADDED stride
						src_row += row_byte_size;
						dst_row += padded_row_byte_size;
					}
				}
				else {
					// No padding required, copy the entire layer at once
					memcpy(dst_layer_start + (i * layer_padded_size), static_cast<uint8_t*>(face_pixels), layer_padded_size);
				}

				if (i > 0 || !src_data_ldr8u) { // Don't free the first face twice
					stbi_image_free(face_pixels);
				}
			}
			stbi_image_free(src_data_ldr8u); // Free first face
		}
		// === HDR cubemaps ===
		else {
			// Pointers for copying layers (using byte pointer for correct layer offset arithmetic)
			uint8_t* dst_data_base = static_cast<uint8_t*>(data);

			// CALCULATE STRIDES IN FLOATS (elements) FOR POINTER ARITHMETIC
			const size_t row_float_count = row_byte_size / sizeof(float_t);
			const size_t padded_row_float_stride = padded_row_byte_size / sizeof(float_t);

			for (int i = 0; i < CUBEMAP_FACE_COUNT; i++) {
				float_t* current_face_pixels = nullptr;

				if (i == 0) {
					current_face_pixels = src_data_hdr32f; // Use the initial loaded data
				}
				else {
					// Load subsequent faces into a new temporary pointer
					std::string face_path = base_path + face_suffixes[i] + extension;
					const char* err = nullptr;
					int result = LoadEXR(&current_face_pixels, &src_width, &src_height, face_path.c_str(), &err);

					if (result != TINYEXR_SUCCESS || !current_face_pixels) {
						Log::warning("In Texture constructor: failed to load cubemap face[", i, "] via TinyEXR. Result: ", err);
						if (err) FreeEXRErrorMessage(err);
						continue;
					}
				}

				// Calculate destination start for the current face in BYTES
				uint8_t* dst_layer_start_bytes = dst_data_base + (i * layer_padded_size);

				// Setup row pointers for copy (cast to float_t* for float arithmetic in loop)
				float_t* dst_row_f = reinterpret_cast<float_t*>(dst_layer_start_bytes);
				const float_t* src_row_f = current_face_pixels;

				if (row_byte_size != padded_row_byte_size) {
					// Copy row by row with padding for the current face
					for (uint32_t y = 0; y < src_height; ++y) {
						// 1. Copy the pixel data for the row (uses correct byte size)
						memcpy(dst_row_f, src_row_f, row_byte_size);

						// 2. Advance pointers using ELEMENT counts (floats)
						src_row_f += row_float_count;
						dst_row_f += padded_row_float_stride;
					}
				}
				else {
					// No padding required, copy the entire layer at once
					memcpy(dst_layer_start_bytes, current_face_pixels, layer_padded_size);
				}

				// Free the memory for the loaded face, ONLY if it was loaded inside the loop (i.e., not the first face)
				if (i > 0 && current_face_pixels) {
					free(current_face_pixels);
				}
			}
			// Free the memory for the first face loaded outside the loop
			free(src_data_hdr32f);
		}
	}
	// === SINGLE 2D TEXTURES: LOAD TO MAPPED MEMORY OF THE STAGING BUFFER ===
	else {
		// === SINGLE 2D LDR TEXTURE ===
		if (src_data_ldr8u) {
			// Pointers for copying
			const uint8_t* src_row = static_cast<const uint8_t*>(src_data_ldr8u);
			uint8_t* dst_row = static_cast<uint8_t*>(data);

			// Using row-by-row copy
			if (row_byte_size != padded_row_byte_size) {
				Log::debug("Applying row padding in staging buffer: ", row_byte_size, " bytes -> ", padded_row_byte_size, " bytes.");
			}
			else {
				// Log this path so we know the failure was in the memcpy.
				Log::debug("No row padding required. Using row-by-row copy for robust memory transfer.");
			}

			for (uint32_t y = 0; y < src_height; ++y) {
				// Copy the actual pixel data for the row
				memcpy(dst_row, src_row, row_byte_size);

				// Advance pointers by the PADDED stride
				src_row += row_byte_size;
				dst_row += padded_row_byte_size; // Destination (staging buffer) is padded
			}

			stbi_image_free(src_data_ldr8u);
		}
		// === SINGLE 2D HDR TEXTURE ===
		else {
			// Pointers for copying
			const float_t* src_data_base = static_cast<const float_t*>(src_data_hdr32f);
			const float_t* current_src_data = src_data_base;
			float_t* dst_data_ptr = static_cast<float_t*>(data);

			// The number of float_t elements in one row (unpadded)
			const size_t row_float_count = row_byte_size / sizeof(float_t);

			// The stride in float_t elements for the destination (padded)
			const size_t padded_row_float_stride = padded_row_byte_size / sizeof(float_t);

			// Conditional check for flip
			bool should_flip = (
				type == TextureType::EQUIRECTANGULAR_HDR_TEXTYPE ||
				type == TextureType::BRDF_LUT_TEXTYPE
			);

			if (should_flip) {
				// If flipping, set the source pointer to the beginning of the LAST row
				current_src_data += (src_height - 1) * row_float_count;
				Log::debug("Image flip requested (EQUIRECTANGULAR_HDR_TEXTYOE). Starting copy from last row to first row.");
			}

			// --- Copy Loop ---
			for (uint32_t y = 0; y < src_height; ++y) {
				memcpy(dst_data_ptr, current_src_data, row_byte_size);	// Copy the pixel data for the row
				dst_data_ptr += padded_row_float_stride;				// Advance the Destination pointer (always moves FORWARD by the padded stride)

				// Advance the Source pointer
				if (should_flip) {
					current_src_data -= row_float_count;
				}
				else {
					current_src_data += row_float_count;
				}
			}
			free(src_data_hdr32f);
		}
	}
	staging_buffer.flush_unmap(0, total_padded_size);

	// === Copy to GPU ===

	cb.begin_recording();

	cb.add_buffer_memory_barrier(				// 1. Barrier for the staging buffer (Host Write -> Transfer Read)
		staging_buffer,
		VK_ACCESS_2_HOST_WRITE_BIT,				// src_access
		VK_ACCESS_2_TRANSFER_READ_BIT,			// dst_access
		VK_PIPELINE_STAGE_2_HOST_BIT,			// src_stage
		VK_PIPELINE_STAGE_2_TRANSFER_BIT		// dst_stage
	);
	cb.record_barriers();

	// Transition mip level 0 (all layers) to TRANSFER_DST_OPTIMAL
	cb.transition_image_layout(					// transition mip 0 (all layers) (Undefined -> Transfer Dst)
		*image,
		0,										// mip_level
		1,										// mip_level_count
		VK_IMAGE_LAYOUT_UNDEFINED,				// old_layout
		VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,	// new_layout
		aspect_mask,							// aspect_mask (from constructor)
		VK_PIPELINE_STAGE_2_TOP_OF_PIPE_BIT,	// src_stage
		VK_ACCESS_2_NONE,						// src_access
		VK_PIPELINE_STAGE_2_TRANSFER_BIT,		// dst_stage
		VK_ACCESS_2_TRANSFER_WRITE_BIT,			// dst_access
		0,										// base_array_layer
		array_layers							// layer_count
	);

	// Copy image to mip level 0 (all layers)
	for (uint32_t layer = 0; layer < array_layers; layer++) {
		VkDeviceSize src_buffer_offset = layer * layer_padded_size;
		cb.copy_buffer_to_image(
			staging_buffer,
			*image,
			src_buffer_offset,						// src buffer offset
			aspect_mask,
			0,										// mip level 0
			layer,									// base array layer
			1,										// layer count
			row_byte_size == padded_row_byte_size	// tightly packed ?
		);
	}

	// Generate mipmaps; includes transition to final layout (SHADER_READ_ONLY_OPTIMAL)
	if (mip_levels > 1) {
		cb.generate_mipmaps(*image);
	}
	else {
		// No mips to generate, just transition Mip 0 (all layers) to its final layout (SHADER_READ_ONLY_OPTIMAL)
		cb.transition_image_layout(
			*image,
			0, // mip level 0
			1, // mip level count
			VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,
			VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL,
			aspect_mask,
			VK_PIPELINE_STAGE_2_TRANSFER_BIT,
			VK_ACCESS_2_TRANSFER_WRITE_BIT,
			VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT,
			VK_ACCESS_2_SHADER_READ_BIT,
			0, // base array layer
			array_layers
		);
	}
	cb.end_recording();

	task.timeline_sync(*tl_semaphore);
	task.submit();

	// Create image view
	image_view = std::make_unique<ImageView>(
		device,
		*image,
		image_view_type,
		aspect_mask,
		0,
		mip_levels,
		0,
		array_layers
	);

	this->unique_ID = next_unique_ID++;
	texture_ID_map[unique_ID] = this;
	this->texture_path = TexturePath(full_filepath_str);
	Texture::tex_list[this->texture_path] = this->unique_ID;
	Log::info("Texture resource creation complete.");
}

// Constructor for creating the resource from a glTF texture
Texture::Texture(
	Device& device,
	const tinygltf::Image& gltf_image,
	VkFormat format,
	Semaphore* tl_semaphore,
	float_t max_anisotropy_level,
	VkSamplerAddressMode sampler_address_mode_U,
	VkSamplerAddressMode sampler_address_mode_V,
	TextureType type,
	int force_mip_levels
) : device(&device) {
	// 1. Get image dimensions and calculate metadata
	// Note: gltf_image.image.size() is the UNPADDED raw data size.
	VkDeviceSize raw_image_size = gltf_image.image.size();
	uint32_t width = static_cast<uint32_t>(gltf_image.width);
	uint32_t height = static_cast<uint32_t>(gltf_image.height);
	uint32_t max_dimension = std::max(width, height);
	const uint32_t required_byte_alignment = 256;
	const uint32_t pixel_bytes = get_format_bytes_per_pixel(format);
	uint32_t row_byte_size = width * pixel_bytes;
	uint32_t padded_row_byte_size = (row_byte_size + required_byte_alignment - 1) / required_byte_alignment * required_byte_alignment;
	VkDeviceSize padded_staging_size = (VkDeviceSize)padded_row_byte_size * height;
	uint32_t mip_levels = 1;
	VkImageAspectFlags aspect_mask = VK_IMAGE_ASPECT_COLOR_BIT;
	if (type == TextureType::LINEAR_TEXTYPE || type == TextureType::SRGB_TEXTYPE) {
		mip_levels = static_cast<uint32_t>(std::floor(std::log2(std::max(width, height)))) + 1;
	}
	if (force_mip_levels >= 0) {
		mip_levels = force_mip_levels;
	}
	VkImageCreateFlags flags = 0;
	uint32_t array_layers = 1;
	VkImageViewType image_view_type = VK_IMAGE_VIEW_TYPE_2D;

	// create Sampler
	sampler = std::make_unique<Sampler>(
		device,
		VK_FILTER_LINEAR,                       // min filter
		VK_FILTER_LINEAR,                       // max filter
		sampler_address_mode_U,					// sampler address mode U
		sampler_address_mode_V,					// sampler address mode V
		VK_SAMPLER_MIPMAP_MODE_LINEAR,          // sampler minmap mode
		mip_levels,
		max_anisotropy_level					// max anisotropy level									
	);

	VulkanManager& manager = VulkanManager::get_singleton();
	Task& task = manager.get_graphics_task();
	CommandBuffer& cb = task.get_command_buffer();

	// Create Staging Buffer
	Log::debug("Texture: Creating staging buffer for ", width, "x", height, " texture");
	Buffer<char8_t>& staging_buffer = task.make_buffer<char8_t>(
		padded_staging_size,
		BufferType::TRANSFER_BUFFER, VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT
	);

	// Create GPU-resident Image
	Log::debug("Texture", "Creating GPU Image with ", mip_levels, " mip levels.");
	image = std::make_unique<Image>(
		device,
		VK_IMAGE_TYPE_2D,
		format,
		VkExtent3D{ width, height, 1 },
		mip_levels,
		array_layers,
		VK_SAMPLE_COUNT_1_BIT,
		VK_IMAGE_TILING_OPTIMAL,
		VK_IMAGE_USAGE_TRANSFER_DST_BIT | VK_IMAGE_USAGE_TRANSFER_SRC_BIT | VK_IMAGE_USAGE_SAMPLED_BIT | VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT,
		VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT,
		VK_IMAGE_LAYOUT_UNDEFINED,
		flags
	);

	// Copy glTF image data to staging buffer row-by-row with padding
	void* data;
	vkMapMemory(device.get_logical(), staging_buffer.get_memory(), 0, padded_staging_size, 0, &data);	// Map the whole padded size
	const char* src_ptr = (const char*)gltf_image.image.data();
	char* dst_ptr = (char*)data;
	for (uint32_t y = 0; y < height; ++y) {
		memcpy(dst_ptr, src_ptr, row_byte_size);	// Copy the actual unpadded row data size
		src_ptr += row_byte_size;					// Advance the source pointer by the actual row data size
		dst_ptr += padded_row_byte_size;			// Advance the destination pointer by the PADDED row size
	}
	vkUnmapMemory(device.get_logical(), staging_buffer.get_memory());

	// === Copy to GPU ===

	cb.begin_recording();

	cb.add_buffer_memory_barrier(				// 1. Barrier for the staging buffer (Host Write -> Transfer Read)
		staging_buffer,
		VK_ACCESS_2_HOST_WRITE_BIT,				// src_access
		VK_ACCESS_2_TRANSFER_READ_BIT,			// dst_access
		VK_PIPELINE_STAGE_2_HOST_BIT,			// src_stage
		VK_PIPELINE_STAGE_2_TRANSFER_BIT		// dst_stage
	);

	// Transition mip level 0 (all layers) to TRANSFER_DST_OPTIMAL
	cb.add_image_memory_barrier(				// 2. Barrier for Mip 0 (all layers) (Undefined -> Transfer Dst)
		*image,
		0,										// mip_level
		VK_IMAGE_LAYOUT_UNDEFINED,				// old_layout
		VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,	// new_layout
		aspect_mask,							// aspect_mask (from constructor)
		VK_PIPELINE_STAGE_2_TOP_OF_PIPE_BIT,	// src_stage
		VK_ACCESS_2_NONE,						// src_access
		VK_PIPELINE_STAGE_2_TRANSFER_BIT,		// dst_stage
		VK_ACCESS_2_TRANSFER_WRITE_BIT,			// dst_access
		0,										// base_array_layer
		array_layers							// layer_count
	);

	cb.record_barriers();

	// Copy image to mip level 0 (all layers)
	cb.copy_buffer_to_image(
		staging_buffer,
		*image,
		0,										// offset
		aspect_mask,
		0,										// mip level 0
		0,										// base array layer
		array_layers,							// layer count
		row_byte_size == padded_row_byte_size	// tightly packed?
	);

	// Generate mipmaps and transition to final layout (SHADER_READ_ONLY_OPTIMAL)
	if (mip_levels > 1) {
		cb.generate_mipmaps(*image);
	}
	else {
		// No mips to generate, just transition Mip 0 (all layers) to its final layout
		cb.transition_image_layout(
			*image,
			0, // mip level 0
			1, // mip level count
			VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,
			VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL,
			aspect_mask,
			VK_PIPELINE_STAGE_2_TRANSFER_BIT,
			VK_ACCESS_2_TRANSFER_WRITE_BIT,
			VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT,
			VK_ACCESS_2_SHADER_READ_BIT,
			0, // base array layer
			array_layers
		);
	}
	cb.end_recording();

	task.timeline_sync(*tl_semaphore);
	task.submit();

	// 5. Create ImageView (using the calculated mip levels)
	image_view = std::make_unique<ImageView>(
		device,
		*image,
		VK_IMAGE_VIEW_TYPE_2D,
		VK_IMAGE_ASPECT_COLOR_BIT,
		0, // base_mip_level
		mip_levels,
		0, // base_array_layer
		array_layers
	);

	this->unique_ID = next_unique_ID++;
	texture_ID_map[unique_ID] = this;
	Log::debug("Texture resource creation from glTF image complete (global unique texture ID: ", this->unique_ID);
}

// create empty texture resource
Texture::Texture(Device& device, uint32_t width, uint32_t height, VkFormat format, Semaphore* tl_semaphore, float_t max_anisotropy_level, VkSamplerAddressMode sampler_address_mode_U, VkSamplerAddressMode sampler_address_mode_V, TextureType type, int force_mip_levels) {
	uint32_t mip_levels = 1;		// use as starting point -> will be modified based on texture type
	VkImageCreateFlags flags = 0;	//  "       "       "        "       "       "       "
	uint32_t array_layers = 1;		//  "       "       "        "       "       "       "
	VkImageViewType image_view_type = VK_IMAGE_VIEW_TYPE_2D;
	VkImageUsageFlags image_usage = VK_IMAGE_USAGE_SAMPLED_BIT | VK_IMAGE_USAGE_TRANSFER_DST_BIT | VK_IMAGE_USAGE_TRANSFER_SRC_BIT | VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT;
	VkImageAspectFlags aspect_mask = VK_IMAGE_ASPECT_COLOR_BIT;
	size_t out_pixel_bytes = get_format_bytes_per_pixel(format);
	VkFormat out_format = format;
	bool out_format_is_hdr = is_hdr(out_format);

	// Determine loading parameters based on texture type
	switch (type) {
		case TextureType::SRGB_TEXTYPE: {
			if (out_format_is_hdr) {
				Log::warning("In Texture constructor: desired format is HDR type. This is incompatible with TextureType::SRGB_TEXTYPE. Switching to VK_FORMAT_R8G8B8A8_RGBA automatically.");
				out_format = VK_FORMAT_R8G8B8A8_SRGB;
			}
			mip_levels = force_mip_levels >= 0 ? force_mip_levels : static_cast<uint32_t>(std::floor(std::log2(std::max(width, height)))) + 1;
			break;
		}

		case TextureType::RGBA_HDR_TEXTYPE: {
			if (!out_format_is_hdr) {
				Log::warning("In Texture constructor: desired format is LDR type. This is incompatible with TextureType::RGBA_HDR_TEXTYPE. Switching to VK_FORMAT_R32G32B32A32_SFLOAT automatically.");
				out_format = VK_FORMAT_R32G32B32A32_SFLOAT;
			}
			mip_levels = force_mip_levels >= 0 ? force_mip_levels : static_cast<uint32_t>(std::floor(std::log2(std::max(width, height)))) + 1;
			break;
		}
		case TextureType::LINEAR_TEXTYPE: {
			if (out_format_is_hdr) {
				Log::warning("In Texture constructor: desired format is HDR type. This is incompatible with TextureType::LINEAR_TEXTYPE. Switching to VK_FORMAT_R8G8B8A8_UNORM automatically.");
				out_format = VK_FORMAT_R8G8B8A8_UNORM;
			}
			mip_levels = force_mip_levels >= 0 ? force_mip_levels : static_cast<uint32_t>(std::floor(std::log2(std::max(width, height)))) + 1;
			break;
		}
		case TextureType::BRDF_LUT_TEXTYPE: {
			if (!out_format_is_hdr) {
				Log::warning("In Texture constructor: desired format is LDR type. This is incompatible with TextureType::BRDF_LUT_TEXTYPE. Switching to VK_FORMAT_R32G32B32A32_SFLOAT automatically.");
				out_format = VK_FORMAT_R32G32B32A32_SFLOAT;
			}
			image_usage |= VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT;
			mip_levels = force_mip_levels >= 0 ? force_mip_levels : 1;
			break;
		}
		case TextureType::EQUIRECTANGULAR_TEXTYPE: {
			if (out_format_is_hdr) {
				Log::warning("In Texture constructor: desired format is HDR type. This is incompatible with TextureType::EQUIRECTANGULAR_TEXTYPE. Switching to VK_FORMAT_R8G8B8A8_SRGB automatically.");
				out_format = VK_FORMAT_R8G8B8A8_SRGB;
			}
			array_layers = 1;
			image_view_type = VK_IMAGE_VIEW_TYPE_2D;
			mip_levels = force_mip_levels >= 0 ? force_mip_levels : 1;
			break;
		}
		case TextureType::EQUIRECTANGULAR_HDR_TEXTYPE: {
			if (!out_format_is_hdr) {
				Log::warning("In Texture constructor: desired format is LDR type. This is incompatible with TextureType::EQUIRECTANGULAR_HDR_TEXTYPE. Switching to VK_FORMAT_R32G32B32A32_SFLOAT automatically.");
				out_format = VK_FORMAT_R32G32B32A32_SFLOAT;
			}
			array_layers = 1;
			image_view_type = VK_IMAGE_VIEW_TYPE_2D;
			mip_levels = force_mip_levels >= 0 ? force_mip_levels : 1;
			break;
		}
		case TextureType::CUBEMAP_TEXTYPE: {
			if (out_format_is_hdr) {
				Log::warning("In Texture constructor: desired format is HDR type. This is incompatible with TextureType::CUBEMAP_TEXTYPE. Switching to VK_FORMAT_R8G8B8A8_SRGB automatically.");
				out_format = VK_FORMAT_R8G8B8A8_SRGB;
			}
			array_layers = CUBEMAP_FACE_COUNT;
			flags = VK_IMAGE_CREATE_CUBE_COMPATIBLE_BIT;
			image_view_type = VK_IMAGE_VIEW_TYPE_CUBE;
			mip_levels = force_mip_levels >= 0 ? force_mip_levels : 1;
			break;
		}
		case TextureType::CUBEMAP_HDR_TEXTYPE: {
			if (!out_format_is_hdr) {
				Log::warning("In Texture constructor: desired format is LDR type. This is incompatible with TextureType::CUBEMAP_HDR_TEXTYPE. Switching to VK_FORMAT_R32G32B32A32_SFLOAT automatically.");
				out_format = VK_FORMAT_R32G32B32A32_SFLOAT;
			}
			// CUBEMAP_HDR is the render target for the equirectangular pass
			image_usage |= VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT;
			array_layers = CUBEMAP_FACE_COUNT;
			flags = VK_IMAGE_CREATE_CUBE_COMPATIBLE_BIT;
			image_view_type = VK_IMAGE_VIEW_TYPE_CUBE;
			mip_levels = force_mip_levels >= 0 ? force_mip_levels : 1;
			break;
		}
		case TextureType::IRRADIANCE_CUBEMAP_TEXTYPE: {
			// IRRADIANCE_CUBEMAP is the render target for the irradiance pass;
			// no format check here, because Scene::process_cubemap already selects the same format as the cubemap source image
			image_usage |= VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT;
			array_layers = CUBEMAP_FACE_COUNT;
			flags = VK_IMAGE_CREATE_CUBE_COMPATIBLE_BIT;
			image_view_type = VK_IMAGE_VIEW_TYPE_CUBE;
			mip_levels = force_mip_levels >= 0 ? force_mip_levels : 1;
			break;
		}
		case TextureType::PREFILTERED_CUBEMAP_TEXTYPE: {
			// PREFILTERED_CUBEMAP is the render target for the prefiltering pass;
			// no format check here, because Scene::process_cubemap already selects the same format as the cubemap source image
			image_usage |= VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT;
			array_layers = CUBEMAP_FACE_COUNT;
			flags = VK_IMAGE_CREATE_CUBE_COMPATIBLE_BIT;
			image_view_type = VK_IMAGE_VIEW_TYPE_CUBE;
			// Prefiltered map needs mip levels for different roughness levels
			mip_levels = force_mip_levels >= 0 ? force_mip_levels : static_cast<uint32_t>(std::floor(std::log2(std::max(width, height)))) + 1;
			break;
		}
		case TextureType::DEPTH_STENCIL_TEXTYPE: {
			image_usage = VK_IMAGE_USAGE_DEPTH_STENCIL_ATTACHMENT_BIT;
			// Remove transfer/sampled flags for pure depth stencil, only attachments are needed
			image_usage &= ~(VK_IMAGE_USAGE_SAMPLED_BIT | VK_IMAGE_USAGE_TRANSFER_DST_BIT | VK_IMAGE_USAGE_TRANSFER_SRC_BIT);
			aspect_mask = VK_IMAGE_ASPECT_DEPTH_BIT;
			mip_levels = force_mip_levels >= 0 ? force_mip_levels : 1;
			break;
		}
	}

	// create Sampler
	sampler = std::make_unique<Sampler>(
		device,
		VK_FILTER_LINEAR,                       // min filter
		VK_FILTER_LINEAR,                       // max filter
		sampler_address_mode_U,					// sampler address mode U
		sampler_address_mode_V,					// sampler address mode V
		VK_SAMPLER_MIPMAP_MODE_LINEAR,          // sampler minmap mode
		mip_levels,
		max_anisotropy_level					// max anisotropy level									
	);

	// Create GPU-resident Image (empty!)
	Log::debug("Texture", "Creating GPU Image with ", mip_levels, " mip levels.");
	image = std::make_unique<Image>(
		device,
		VK_IMAGE_TYPE_2D,
		out_format,
		VkExtent3D{ width, height, 1 },
		mip_levels,
		array_layers,
		VK_SAMPLE_COUNT_1_BIT,
		VK_IMAGE_TILING_OPTIMAL,
		image_usage,
		VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT,
		VK_IMAGE_LAYOUT_UNDEFINED,
		flags
	);

	// Create ImageView (empty!)
	image_view = std::make_unique<ImageView>(
		device,
		*image,
		image_view_type,
		aspect_mask,
		0, // base_mip_level
		mip_levels,
		0, // base_array_layer
		array_layers
	);

	this->unique_ID = next_unique_ID++;
	texture_ID_map[unique_ID] = this;
	Log::debug("Texture resource creation complete (global unique texture ID: ", this->unique_ID);
}

// Destructor
Texture::~Texture() {
	tex_list.erase(this->texture_path);
	texture_ID_map.erase(this->unique_ID);
}

// Getters
ImageView& Texture::get_image_view() const { return *image_view; }
Sampler& Texture::get_sampler() const { return *sampler; }
Image& Texture::get_image() const { return *image; }
const uint32_t Texture::get_unique_ID() const { return unique_ID; }
uint32_t Texture::get_next_unique_ID() { return next_unique_ID; }
const int Texture::get_unique_IDs_count() { return next_unique_ID; }

Texture* Texture::get_texture_by_ID(uint32_t global_texID) {
	auto it = texture_ID_map.find(global_texID);
	if (it == texture_ID_map.end()) {
		return nullptr;
	}
	else {
		return it->second;
	}
}

int Texture::get_unique_ID(std::string texture_path) {
	return get_unique_ID(TexturePath(texture_path));
}

int Texture::get_unique_ID(TexturePath texture_path) {
	auto it = tex_list.find(texture_path);
	if (it == tex_list.end()) {
		return -1;
	}
	else {
		return it->second;
	}
}

const TexturePath& Texture::register_path(const std::string& filepath) {
	if (this->texture_path.pre_calculated_hash != 0) {
		Log::warning("in Texture::register_path(): this texture has already been registered (path: ", this->texture_path.path, ", hash: ", this->texture_path.pre_calculated_hash, ")");
	}
	this->texture_path = TexturePath(filepath);
	Texture::tex_list[this->texture_path] = this->unique_ID;
	return this->texture_path;
}


// +=================================+   
// | Vertex                          |
// +=================================+

// helper method to provide a hash function for std::unordered_map (required for the Mesh class)
namespace std {
	template<> struct hash<Vertex> {
		size_t operator()(Vertex const& vertex) const {
			// The seed starts with the hash of the first component.
			size_t seed = hash<glm::vec3>{}(vertex.position);

			// lambda to perform the hash combination
			auto combine = [&](const auto& v) {
				size_t hash_val = std::hash<std::decay_t<decltype(v)>>{}(v);
				// This formula mixes the bits effectively using the golden ratio constant.
				seed ^= hash_val + 0x9e3779b9 + (seed << 6) + (seed >> 2);
				};

			// Apply the combination logic sequentially for the remaining members
			combine(vertex.normal);
			combine(vertex.tex_coord);

			return seed;
		}
	};
}

bool Vertex::operator==(const Vertex& other) const {
	// Define the tolerance (epsilon) locally.
	const float EPSILON = 1e-6;

	// 1. Lambda for comparing two glm::vec3 objects.
	auto IsNear3 = [&](const glm::vec3& a, const glm::vec3& b) {
		return std::abs(a.x - b.x) < EPSILON &&
			std::abs(a.y - b.y) < EPSILON &&
			std::abs(a.z - b.z) < EPSILON;
		};

	// 2. Lambda for comparing two glm::vec2 objects.
	auto IsNear2 = [&](const glm::vec2& a, const glm::vec2& b) {
		return std::abs(a.x - b.x) < EPSILON &&
			std::abs(a.y - b.y) < EPSILON;
		};

	// Perform the component-wise checks for all members
	return
		// 3D Comparisons (Position, Normal, Color, Tangent)
		IsNear3(this->position, other.position) &&
		IsNear3(this->normal, other.normal) &&
		IsNear3(this->color, other.color) &&
		IsNear3(this->tangent, other.tangent) &&

		// 2D Comparison (Tex_Coord)
		IsNear2(this->tex_coord, other.tex_coord);
}

