// Constructor with vectors
Camera::Camera(glm::vec3 camera_position, glm::vec3 camera_up, float camera_yaw, float camera_pitch) : unique_ID(next_unique_ID++) {
	position = camera_position;
	world_up = camera_up;
	yaw = camera_yaw;
	pitch = camera_pitch;
}

// Constructor with scalar values
Camera::Camera(float pos_x, float pos_y, float pos_z, float up_x, float up_y, float up_z, float camera_yaw, float camera_pitch) : unique_ID(next_unique_ID++) {
	position = glm::vec3(pos_x, pos_y, pos_z);
	world_up = glm::vec3(up_x, up_y, up_z);
	yaw = camera_yaw;
	pitch = camera_pitch;
}

int Camera::get_unique_ID() const {
	return unique_ID;
}

// Returns the view matrix calculated using Euler Angles and the LookAt Matrix
// (for free-look (FPS style) camera)
glm::mat4 Camera::get_view_matrix() {
	// update the front vector
	glm::vec3 new_front;
	new_front.x = cos(glm::radians(yaw)) * cos(glm::radians(pitch));
	new_front.y = sin(glm::radians(pitch));
	new_front.z = sin(glm::radians(yaw)) * cos(glm::radians(pitch));
	front = glm::normalize(new_front);

	// update right and up vector
	right = glm::normalize(glm::cross(front, world_up));
	up = glm::normalize(glm::cross(right, front));

	return glm::lookAt(position, position + front, up);
}

// Returns the projection matrix
glm::mat4 Camera::get_projection_matrix() {
	glm::mat4 projection = glm::perspective(glm::radians(fov), aspect_ratio, near_plane, far_plane);

	// VULKAN FIX 1: Flip the Y-axis of the projection matrix (not necessary for OpenGL)
	projection[1][1] *= -1;

	// VULKAN FIX 2: Manually correct the Z-depth range from [-1, 1] to [0, 1]
	// The two matrix cells responsible for the Z-coordinate transformation (index 2)
	projection[2][2] *= 0.5f; // Scales the depth by 0.5
	projection[2][3] += projection[2][2]; // Shifts the depth by 0.5

	return projection;
}

// return the current camera position
glm::vec3 Camera::get_position() const {
	return position;
}

// Sets the camera's position.
glm::vec3 Camera::set_position(const glm::vec3& new_position) {
	this->position = new_position;
	return position;
}

// translate the camera's position by the specified delta
glm::vec3 Camera::translate(const glm::vec3& delta) {
	this->position += delta;
	return position;
}

// Sets the world up vector.
void Camera::set_world_up(const glm::vec3& new_world_up) {
	this->world_up = new_world_up;
}

// Sets the yaw angle.
void Camera::set_yaw(float new_yaw) {
	this->yaw = new_yaw;
}

// Sets the pitch angle.
void Camera::set_pitch(float new_pitch) {
	this->pitch = new_pitch;
	// Make sure that when pitch is out of bounds, screen doesn't get flipped
	if (pitch > 89.0f) {
		pitch = 89.0f;
	}
	if (pitch < -89.0f) {
		pitch = -89.0f;
	}
}

// Sets the movement speed.
void Camera::set_movement_speed(float new_speed) {
	this->movement_speed = new_speed;
}

// Sets the mouse sensitivity.
void Camera::set_mouse_sensitivity(float new_sensitivity) {
	this->mouse_sensitivity = new_sensitivity;
}

// Sets the field of view.
void Camera::set_fov(float new_fov) {
	this->fov = new_fov;
	if (this->fov < 1.0f) {
		this->fov = 1.0f;
	}
	if (this->fov > 45.0f) {
		this->fov = 45.0f;
	}
}

// Sets the aspect ratio.
void Camera::set_aspect_ratio(float new_aspect_ratio) {
	this->aspect_ratio = new_aspect_ratio;
}

void Camera::set_aspect_ratio(VkExtent2D extent) {
	aspect_ratio = float_t(extent.width) / extent.height;
}

// Sets the near plane distance.
void Camera::set_near_plane(float new_near_plane) {
	this->near_plane = new_near_plane;
}

// Sets the far plane distance.
void Camera::set_far_plane(float new_far_plane) {
	this->far_plane = new_far_plane;
}

// Processes input received from any keyboard-like input system.
void Camera::process_keyboard(CameraMovement direction, float delta_time) {
	float velocity = movement_speed * delta_time;
	if (direction == CameraMovement::CAMERA_FORWARD)
		position += front * velocity;
	if (direction == CameraMovement::CAMERA_BACKWARD)
		position -= front * velocity;
	if (direction == CameraMovement::CAMERA_LEFT)
		position -= right * velocity;
	if (direction == CameraMovement::CAMERA_RIGHT)
		position += right * velocity;
	if (direction == CameraMovement::CAMERA_UP)
		position += world_up * velocity;
	if (direction == CameraMovement::CAMERA_DOWN)
		position -= world_up * velocity;
}

// Processes input received from a mouse input system.
void Camera::process_mouse_movement(float x_offset, float y_offset, bool constrain_pitch) {
	x_offset *= mouse_sensitivity;
	y_offset *= mouse_sensitivity;

	yaw += x_offset;
	pitch += y_offset;

	// Make sure that when pitch is out of bounds, screen doesn't get flipped
	if (constrain_pitch) {
		if (pitch > 89.0f)
			pitch = 89.0f;
		if (pitch < -89.0f)
			pitch = -89.0f;
	}
}

// Processes input received from a mouse scroll-wheel event.
void Camera::process_mouse_scroll(float y_offset) {
	set_fov(fov - y_offset);
}

